  const hiddenIds = editing
    ? queryHiddenIds
    : new Set([...logicHiddenIds, ...queryHiddenIds]);

  // Judged against the query filter alone — in preview a top-level question
  // hidden by enable_when must not make a matching search read as "no
  // matches".
  const noMatches =
