import { SubjectType } from "./questionnaire";

/**
 * Questionnaire actions — server-side automations evaluated when a
 * patient/encounter questionnaire is submitted (`POST …/submit/`). The
 * backend (care `action_evaluator`) runs each action's `condition` over the
 * cleaned answers (`q_<link_id>`) and the context graph (`patient["age"]`),
 * then executes its instructions in order.
 *
 * Wire shape — `care/action_evaluator/base.py` `Action`/`Instruction`:
 * `condition` is a Python-subset expression string (`evalidate`), REQUIRED
 * (an empty string never fires — "always" is the literal `True`);
 * `instructions[].context` is a context PATH from the submission root
 * (`self`, `patient`, …), REQUIRED; `slug` must name a registered
 * instruction (save fails with 400 otherwise).
 */
export interface QuestionnaireActionInstruction {
  slug: string;
  /** Instruction inputs per its `input_schema`. A string value wrapped
   *  entirely in `{{ … }}` is evaluated as an expression at run time. */
  params: Record<string, unknown>;
  context: string;
}

export interface QuestionnaireAction {
  condition: string;
  instructions: QuestionnaireActionInstruction[];
}

/** `care/action_evaluator/instruction_engine/base.py` `InstructionType`. */
export const ACTION_INSTRUCTION_TYPES = [
  "REDIRECT",
  "PERFORMED",
  "NOTIFY",
  "TEXT",
  "VALIDATE",
] as const;

export type ActionInstructionType = (typeof ACTION_INSTRUCTION_TYPES)[number];

/** The subset of JSON Schema pydantic emits for an instruction's input
 *  model that the param editor understands; anything richer falls back to
 *  the JSON textarea. */
export interface ActionParamSchema {
  type?: string | string[];
  title?: string;
  description?: string;
  enum?: unknown[];
  default?: unknown;
  /** Pydantic renders `str | None` as `anyOf: [{type: string}, {type: null}]`. */
  anyOf?: ActionParamSchema[];
}

export interface ActionInputSchema {
  type?: string;
  title?: string;
  properties?: Record<string, ActionParamSchema>;
  required?: string[];
}

/** `GET /api/v1/action_configuration/instructions/` entry —
 *  `BaseInstruction.render_dict`. */
export interface ActionInstructionDefinition {
  slug: string;
  input_schema: ActionInputSchema;
  output_schema: unknown;
  /** The context TYPE the instruction declares (informational — the
   *  backend does not enforce it against the resolved `context` path). */
  context: string;
  instruction_type: ActionInstructionType | (string & {});
}

/** `GET /api/v1/action_configuration/fields/` entry —
 *  `ActionContextFieldBase.render_dict`. A field with `target_context_type`
 *  is an edge to another context (`patient` → `Patient`); without it the
 *  field is a leaf value (`age`). */
export interface ActionContextField {
  context_type: string;
  field: string;
  evaluation: "static" | "global" | "dynamic";
  target_context_type?: string;
}

/** One entry of the submit response's `_actions` — `do_evaluate` output. */
export interface ActionOutcome {
  slug: string;
  instruction_type: ActionInstructionType | (string & {});
  results: unknown;
}

/**
 * The context type the backend evaluates a questionnaire's actions under
 * (`QuestionnaireViewSet.submit`): encounter questionnaires run as
 * `EncounterQuestionnaire`, patient ones as `PatientQuestionnaire`. The
 * resource submit path (location/device/facility) never evaluates actions,
 * so those subject types have no context — the studio hides authoring for
 * them.
 */
export function actionContextTypeFor(
  subjectType: SubjectType,
): "EncounterQuestionnaire" | "PatientQuestionnaire" | null {
  switch (subjectType) {
    case "encounter":
      return "EncounterQuestionnaire";
    case "patient":
      return "PatientQuestionnaire";
    default:
      return null;
  }
}

import { HttpMethod, Type } from "@/Utils/request/types";

import { ActionContextField, ActionInstructionDefinition } from "./actions";

/** The action registry — what the backend can run and what a condition may
 *  reference. Process-wide and static per deployment
 *  (`ActionConfigurationViewSet` serves module-level registries). */
export default {
  instructions: {
    path: "/api/v1/action_configuration/instructions/",
    method: HttpMethod.GET,
    TRes: Type<{ instructions: ActionInstructionDefinition[] }>(),
  },
  fields: {
    path: "/api/v1/action_configuration/fields/",
    method: HttpMethod.GET,
    TRes: Type<{ fields: ActionContextField[] }>(),
  },
} as const;

/**
 * The bridge between the action editor's structured rules and the raw
 * expression strings the backend stores and evaluates.
 *
 * The backend evaluates `condition` (and any `{{ … }}` instruction param)
 * with `evalidate` over a whitelist of Python nodes: names, constants,
 * subscripts, comparisons, `in`/`not in`, `and`/`or`/`not`, arithmetic and
 * f-strings — NO attribute access (`patient.age` is rejected; it must be
 * `patient["age"]`), NO list literals, NO calls. Question answers are the
 * names `q_<link_id>` (present only when answered), context values are
 * subscript chains from the submission root (`patient["age"]`).
 *
 * The editor emits one canonical subset and only ever parses that subset
 * back: clauses of the form `ref OP literal` or `literal in ref` /
 * `literal not in ref`, joined by a single connective. Anything else a
 * human wrote (parentheses, arithmetic, f-strings) is a "custom expression"
 * — kept verbatim, edited as text, never rewritten.
 *
 * Refs are represented as dotted paths on this side (`q_fever`,
 * `patient.age`) and compiled to Python on the way out.
 */

export type ActionRuleOperator =
  | "=="
  | "!="
  | ">"
  | ">="
  | "<"
  | "<="
  | "in"
  | "not in";

export type ActionRuleValue = string | number | boolean;

export interface ActionRule {
  /** `q_<link_id>` for an answer, or a context path such as `patient.age`. */
  ref: string;
  operator: ActionRuleOperator;
  value: ActionRuleValue;
}

export type ActionRuleBehavior = "all" | "any";

export interface ParsedCondition {
  rules: ActionRule[];
  behavior: ActionRuleBehavior;
}

export const ACTION_RULE_OPERATORS: readonly ActionRuleOperator[] = [
  "==",
  "!=",
  ">",
  ">=",
  "<",
  "<=",
  "in",
  "not in",
];

/** The literal the backend's `Action.condition` needs to fire on every
 *  submission — an EMPTY condition never fires. */
export const ALWAYS_CONDITION = "True";

const QUESTION_REF_PREFIX = "q_";

/** A link_id usable as a condition variable: `q_` + link_id must be a Python
 *  identifier, so only `[A-Za-z0-9_]` survive (the studio's default
 *  `Q-xxxxxxxx` link ids carry a hyphen and cannot be referenced). */
export function isIdentifierSafeLinkId(linkId: string): boolean {
  return /^[A-Za-z0-9_]+$/.test(linkId);
}

export function questionRef(linkId: string): string {
  return QUESTION_REF_PREFIX + linkId;
}

/** The link_id a `q_…` ref names, or undefined for context refs. */
export function linkIdOfRef(ref: string): string | undefined {
  return ref.startsWith(QUESTION_REF_PREFIX) && !ref.includes(".")
    ? ref.slice(QUESTION_REF_PREFIX.length)
    : undefined;
}

// ---------------------------------------------------------------------------
// Tokenizer — position-preserving so `remapQuestionRefs` can rewrite names
// without touching string literals or anything it does not understand.

type Token =
  | { kind: "string"; value: string; start: number; end: number }
  | { kind: "number"; value: number; start: number; end: number }
  | { kind: "ident"; value: string; start: number; end: number }
  | { kind: "op"; value: string; start: number; end: number }
  | { kind: "other"; value: string; start: number; end: number };

const IDENT_START = /[A-Za-z_]/;
const IDENT_PART = /[A-Za-z0-9_]/;
const DIGIT = /[0-9]/;
const TWO_CHAR_OPS = ["==", "!=", ">=", "<="];
const ONE_CHAR_OPS = "><[]()+-*/%,";

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let index = 0;
  while (index < source.length) {
    const char = source[index];
    if (/\s/.test(char)) {
      index += 1;
      continue;
    }
    if (char === '"' || char === "'") {
      const start = index;
      let cursor = index + 1;
      let closed = false;
      let value = "";
      while (cursor < source.length) {
        const current = source[cursor];
        if (current === "\\" && cursor + 1 < source.length) {
          value += current + source[cursor + 1];
          cursor += 2;
          continue;
        }
        if (current === char) {
          closed = true;
          cursor += 1;
          break;
        }
        value += current;
        cursor += 1;
      }
      if (!closed) {
        tokens.push({
          kind: "other",
          value: source.slice(start),
          start,
          end: source.length,
        });
        break;
      }
      const decoded = decodeStringLiteral(value, char);
      tokens.push(
        decoded === undefined
          ? { kind: "other", value: source.slice(start, cursor), start, end: cursor }
          : { kind: "string", value: decoded, start, end: cursor },
      );
      index = cursor;
      continue;
    }
    if (DIGIT.test(char)) {
      const start = index;
      let cursor = index;
      while (cursor < source.length && DIGIT.test(source[cursor])) cursor += 1;
      if (
        source[cursor] === "." &&
        cursor + 1 < source.length &&
        DIGIT.test(source[cursor + 1])
      ) {
        cursor += 1;
        while (cursor < source.length && DIGIT.test(source[cursor])) {
          cursor += 1;
        }
      }
      tokens.push({
        kind: "number",
        value: Number(source.slice(start, cursor)),
        start,
        end: cursor,
      });
      index = cursor;
      continue;
    }
    if (IDENT_START.test(char)) {
      const start = index;
      let cursor = index;
      while (cursor < source.length && IDENT_PART.test(source[cursor])) {
        cursor += 1;
      }
      tokens.push({
        kind: "ident",
        value: source.slice(start, cursor),
        start,
        end: cursor,
      });
      index = cursor;
      continue;
    }
    const pair = source.slice(index, index + 2);
    if (TWO_CHAR_OPS.includes(pair)) {
      tokens.push({ kind: "op", value: pair, start: index, end: index + 2 });
      index += 2;
      continue;
    }
    if (ONE_CHAR_OPS.includes(char)) {
      tokens.push({ kind: "op", value: char, start: index, end: index + 1 });
      index += 1;
      continue;
    }
    tokens.push({ kind: "other", value: char, start: index, end: index + 1 });
    index += 1;
  }
  return tokens;
}

/** Decodes the body of a Python string literal. Double-quoted bodies go
 *  through JSON (the same escapes, and exactly what `compile` emits);
 *  single-quoted ones are accepted only when trivially convertible. */
function decodeStringLiteral(body: string, quote: string): string | undefined {
  try {
    if (quote === '"') return JSON.parse(`"${body}"`) as string;
    if (body.includes("\\") || body.includes('"')) return undefined;
    return body;
  } catch {
    return undefined;
  }
}

// ---------------------------------------------------------------------------
// Compile

function compileRef(ref: string): string {
  const [root, ...keys] = ref.split(".");
  return root + keys.map((key) => `[${JSON.stringify(key)}]`).join("");
}

function compileLiteral(value: ActionRuleValue): string {
  if (typeof value === "boolean") return value ? "True" : "False";
  if (typeof value === "number") {
    return Number.isFinite(value) ? String(value) : "0";
  }
  return JSON.stringify(value);
}

function compileRule(rule: ActionRule): string {
  const ref = compileRef(rule.ref);
  const literal = compileLiteral(rule.value);
  if (rule.operator === "in" || rule.operator === "not in") {
    return `${literal} ${rule.operator} ${ref}`;
  }
  return `${ref} ${rule.operator} ${literal}`;
}

/** Rules → the backend expression. No rules → `True` (always fires). */
export function compileCondition(
  rules: ActionRule[],
  behavior: ActionRuleBehavior,
): string {
  if (rules.length === 0) return ALWAYS_CONDITION;
  return rules.map(compileRule).join(behavior === "any" ? " or " : " and ");
}

/** A whole-value instruction param that evaluates `ref` at run time. */
export function compileTemplate(ref: string): string {
  return `{{ ${compileRef(ref)} }}`;
}

// ---------------------------------------------------------------------------
// Parse (canonical subset only)

/** `ident ( "[" string "]" )*` → dotted path, consuming from `from`. */
function readRef(
  tokens: Token[],
  from: number,
): { ref: string; next: number } | null {
  const head = tokens[from];
  if (!head || head.kind !== "ident" || isKeyword(head.value)) return null;
  const segments = [head.value];
  let cursor = from + 1;
  while (
    tokens[cursor]?.kind === "op" &&
    tokens[cursor].value === "[" &&
    tokens[cursor + 1]?.kind === "string" &&
    tokens[cursor + 2]?.kind === "op" &&
    tokens[cursor + 2].value === "]"
  ) {
    const key = (tokens[cursor + 1] as Extract<Token, { kind: "string" }>)
      .value;
    if (!IDENT_START.test(key[0] ?? "") || !/^[A-Za-z0-9_]+$/.test(key)) {
      return null;
    }
    segments.push(key);
    cursor += 3;
  }
  return { ref: segments.join("."), next: cursor };
}

function readLiteral(
  tokens: Token[],
  from: number,
): { value: ActionRuleValue; next: number } | null {
  const token = tokens[from];
  if (!token) return null;
  if (token.kind === "string") return { value: token.value, next: from + 1 };
  if (token.kind === "number") return { value: token.value, next: from + 1 };
  if (
    token.kind === "op" &&
    token.value === "-" &&
    tokens[from + 1]?.kind === "number"
  ) {
    return {
      value: -(tokens[from + 1] as Extract<Token, { kind: "number" }>).value,
      next: from + 2,
    };
  }
  if (token.kind === "ident" && token.value === "True") {
    return { value: true, next: from + 1 };
  }
  if (token.kind === "ident" && token.value === "False") {
    return { value: false, next: from + 1 };
  }
  return null;
}

const KEYWORDS = new Set(["and", "or", "not", "in", "True", "False", "None"]);

function isKeyword(word: string): boolean {
  return KEYWORDS.has(word);
}

const COMPARISON_OPERATORS = new Set(["==", "!=", ">", ">=", "<", "<="]);

function parseClause(tokens: Token[]): ActionRule | null {
  // `literal in ref` / `literal not in ref`
  const literalFirst = readLiteral(tokens, 0);
  if (literalFirst) {
    let cursor = literalFirst.next;
    let operator: ActionRuleOperator | undefined;
    if (tokens[cursor]?.kind === "ident" && tokens[cursor].value === "in") {
      operator = "in";
      cursor += 1;
    } else if (
      tokens[cursor]?.kind === "ident" &&
      tokens[cursor].value === "not" &&
      tokens[cursor + 1]?.kind === "ident" &&
      tokens[cursor + 1].value === "in"
    ) {
      operator = "not in";
      cursor += 2;
    }
    if (operator) {
      const ref = readRef(tokens, cursor);
      if (!ref || ref.next !== tokens.length) return null;
      return { ref: ref.ref, operator, value: literalFirst.value };
    }
  }
  // `ref OP literal`
  const ref = readRef(tokens, 0);
  if (!ref) return null;
  const opToken = tokens[ref.next];
  if (
    !opToken ||
    opToken.kind !== "op" ||
    !COMPARISON_OPERATORS.has(opToken.value)
  ) {
    return null;
  }
  const literal = readLiteral(tokens, ref.next + 1);
  if (!literal || literal.next !== tokens.length) return null;
  return {
    ref: ref.ref,
    operator: opToken.value as ActionRuleOperator,
    value: literal.value,
  };
}

/**
 * The structured reading of a stored condition, or null when it is not in
 * the canonical subset the editor emits (the caller then shows it as a
 * custom expression). `True` reads as "no rules".
 */
export function parseCondition(expression: string): ParsedCondition | null {
  const tokens = tokenize(expression);
  if (tokens.length === 0) return null;
  if (tokens.some((token) => token.kind === "other")) return null;
  if (
    tokens.length === 1 &&
    tokens[0].kind === "ident" &&
    tokens[0].value === "True"
  ) {
    return { rules: [], behavior: "all" };
  }

  const groups: Token[][] = [[]];
  let behavior: ActionRuleBehavior | undefined;
  for (const token of tokens) {
    if (
      token.kind === "ident" &&
      (token.value === "and" || token.value === "or")
    ) {
      const next: ActionRuleBehavior = token.value === "and" ? "all" : "any";
      if (behavior && behavior !== next) return null;
      behavior = next;
      groups.push([]);
      continue;
    }
    groups[groups.length - 1].push(token);
  }

  const rules: ActionRule[] = [];
  for (const group of groups) {
    const rule = parseClause(group);
    if (!rule) return null;
    rules.push(rule);
  }
  return { rules, behavior: behavior ?? "all" };
}

export type ParsedTemplate =
  | { kind: "ref"; ref: string }
  | { kind: "expression"; expression: string };

/** Reads a `{{ … }}` param: a bare ref the picker can display, a custom
 *  expression, or null when the value is a plain literal. */
export function parseTemplate(value: unknown): ParsedTemplate | null {
  if (typeof value !== "string") return null;
  const match = /^\{\{([\s\S]*)\}\}$/.exec(value.trim());
  if (!match) return null;
  const inner = match[1].trim();
  const tokens = tokenize(inner);
  const ref = tokens.length > 0 ? readRef(tokens, 0) : null;
  if (ref && ref.next === tokens.length) return { kind: "ref", ref: ref.ref };
  return { kind: "expression", expression: inner };
}

// ---------------------------------------------------------------------------
// Reference inspection and rewriting

/** Every `q_<link_id>` name an expression reads — canonical or not. */
export function referencedLinkIds(expression: string): string[] {
  const seen = new Set<string>();
  for (const token of tokenize(expression)) {
    if (token.kind !== "ident") continue;
    const linkId = linkIdOfRef(token.value);
    if (linkId) seen.add(linkId);
  }
  return [...seen];
}

/** Rewrites `q_<old>` names per `linkIdMap`, leaving string literals and
 *  everything else byte-identical. */
export function remapQuestionRefs(
  expression: string,
  linkIdMap: ReadonlyMap<string, string>,
): string {
  let output = "";
  let cursor = 0;
  for (const token of tokenize(expression)) {
    if (token.kind !== "ident") continue;
    const linkId = linkIdOfRef(token.value);
    const replacement = linkId ? linkIdMap.get(linkId) : undefined;
    if (!replacement) continue;
    output += expression.slice(cursor, token.start) + questionRef(replacement);
    cursor = token.end;
  }
  return output + expression.slice(cursor);
}

/** The `{{ … }}` inner expression of a param, rewritten and re-wrapped. */
function remapTemplateParam(
  value: unknown,
  linkIdMap: ReadonlyMap<string, string>,
): unknown {
  if (typeof value !== "string") return value;
  const match = /^(\s*\{\{)([\s\S]*)(\}\}\s*)$/.exec(value);
  if (!match) return value;
  return match[1] + remapQuestionRefs(match[2], linkIdMap) + match[3];
}

/** Every answer reference inside an action (its condition plus any
 *  templated param) — for validation and the clone remap. */
export function actionReferencedLinkIds(action: {
  condition: string;
  instructions: { params: Record<string, unknown> }[];
}): string[] {
  const seen = new Set(referencedLinkIds(action.condition));
  for (const instruction of action.instructions) {
    for (const value of Object.values(instruction.params)) {
      const template = parseTemplate(value);
      if (!template) continue;
      const inner =
        template.kind === "ref" ? template.ref : template.expression;
      for (const linkId of referencedLinkIds(inner)) seen.add(linkId);
    }
  }
  return [...seen];
}

/** Clone support: follow `regenerateQuestionIds`' link_id map through every
 *  condition and templated param so the copy's actions still point at the
 *  copy's questions. */
export function remapActionLinkIds<
  T extends {
    condition: string;
    instructions: { params: Record<string, unknown> }[];
  },
>(actions: T[], linkIdMap: ReadonlyMap<string, string>): T[] {
  return actions.map((action) => ({
    ...action,
    condition: remapQuestionRefs(action.condition, linkIdMap),
    instructions: action.instructions.map((instruction) => ({
      ...instruction,
      params: Object.fromEntries(
        Object.entries(instruction.params).map(([key, value]) => [
          key,
          remapTemplateParam(value, linkIdMap),
        ]),
      ),
    })),
  }));
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import {
  ALWAYS_CONDITION,
  actionReferencedLinkIds,
  compileCondition,
  compileTemplate,
  isIdentifierSafeLinkId,
  linkIdOfRef,
  parseCondition,
  parseTemplate,
  referencedLinkIds,
  remapActionLinkIds,
  remapQuestionRefs,
} from "./actionExpression";

describe("compileCondition", () => {
  it("emits True for no rules — an empty condition never fires", () => {
    assert.equal(compileCondition([], "all"), ALWAYS_CONDITION);
    assert.equal(compileCondition([], "any"), "True");
  });

  it("compiles every value shape the backend's cleaned answers take", () => {
    assert.equal(
      compileCondition(
        [
          { ref: "q_fever", operator: "==", value: true },
          { ref: "q_temp", operator: ">", value: 38.5 },
          { ref: "q_severity", operator: "!=", value: "severe" },
          { ref: "q_symptoms", operator: "in", value: "rash" },
          { ref: "q_symptoms", operator: "not in", value: "cough" },
          { ref: "q_count", operator: "<=", value: -2 },
        ],
        "all",
      ),
      'q_fever == True and q_temp > 38.5 and q_severity != "severe" and "rash" in q_symptoms and "cough" not in q_symptoms and q_count <= -2',
    );
  });

  it("compiles context paths as subscript chains (evalidate rejects attribute access)", () => {
    assert.equal(
      compileCondition(
        [{ ref: "patient.age", operator: ">=", value: 18 }],
        "any",
      ),
      'patient["age"] >= 18',
    );
  });

  it("joins with or for any-behaviour", () => {
    assert.equal(
      compileCondition(
        [
          { ref: "q_a", operator: "==", value: "x" },
          { ref: "q_b", operator: "==", value: "y" },
        ],
        "any",
      ),
      'q_a == "x" or q_b == "y"',
    );
  });

  it("JSON-quotes strings so quotes and backslashes survive", () => {
    assert.equal(
      compileCondition(
        [{ ref: "q_note", operator: "==", value: 'say "hi"\\now' }],
        "all",
      ),
      'q_note == "say \\"hi\\"\\\\now"',
    );
  });
});

describe("parseCondition", () => {
  it("round-trips everything compileCondition emits", () => {
    const rules = [
      { ref: "q_fever", operator: "==" as const, value: true },
      { ref: "patient.age", operator: ">=" as const, value: 18 },
      { ref: "q_severity", operator: "!=" as const, value: 'se"vere' },
      { ref: "q_symptoms", operator: "in" as const, value: "rash" },
      { ref: "q_symptoms", operator: "not in" as const, value: "cough" },
      { ref: "q_temp", operator: "<" as const, value: -0.5 },
    ];
    for (const behavior of ["all", "any"] as const) {
      const parsed = parseCondition(compileCondition(rules, behavior));
      assert.deepEqual(parsed, { rules, behavior });
    }
  });

  it("reads True as no rules", () => {
    assert.deepEqual(parseCondition("True"), { rules: [], behavior: "all" });
    assert.deepEqual(parseCondition("  True  "), {
      rules: [],
      behavior: "all",
    });
  });

  it("accepts single-quoted strings and loose whitespace a human typed", () => {
    assert.deepEqual(parseCondition("q_a=='x'   and   q_b >= 3"), {
      rules: [
        { ref: "q_a", operator: "==", value: "x" },
        { ref: "q_b", operator: ">=", value: 3 },
      ],
      behavior: "all",
    });
  });

  it("returns null for anything outside the canonical subset", () => {
    for (const expression of [
      "",
      "   ",
      "q_a == 'x' and q_b == 'y' or q_c == 'z'", // mixed connectives
      "(q_a == 'x')", // parentheses
      "q_temp * 2 > 70", // arithmetic
      "not q_flag", // unary
      "q_flag", // bare truthiness
      'q_a == "unterminated',
      "q_a == None",
      "q_a in ['x', 'y']", // list literal (evalidate rejects it too)
      "patient.age > 18", // attribute access (evalidate rejects it)
      'patient["not an ident"] > 1',
      "q_a ==",
      'f"{q_a}" == "x"',
      'q_a == "x" == "y"',
    ]) {
      assert.equal(parseCondition(expression), null, expression);
    }
  });
});

describe("templates", () => {
  it("compiles a whole-value template the backend evaluates", () => {
    assert.equal(compileTemplate("q_temp"), "{{ q_temp }}");
    assert.equal(compileTemplate("patient.age"), '{{ patient["age"] }}');
  });

  it("parses refs, custom expressions and plain literals apart", () => {
    assert.deepEqual(parseTemplate("{{ q_temp }}"), {
      kind: "ref",
      ref: "q_temp",
    });
    assert.deepEqual(parseTemplate('{{patient["age"]}}'), {
      kind: "ref",
      ref: "patient.age",
    });
    assert.deepEqual(parseTemplate('{{ f"temp {q_temp}" }}'), {
      kind: "expression",
      expression: 'f"temp {q_temp}"',
    });
    assert.equal(parseTemplate("plain text"), null);
    assert.equal(parseTemplate(42), null);
    assert.equal(parseTemplate("{{ partial }} text"), null);
  });
});

describe("references", () => {
  it("lists q_ names, ignoring string literals and context refs", () => {
    assert.deepEqual(
      referencedLinkIds('q_a == "q_not_a_ref" and patient["age"] > q_b'),
      ["a", "b"],
    );
    assert.deepEqual(referencedLinkIds('f"{q_temp} and {q_temp}"'), ["temp"]);
  });

  it("collects references from the condition and templated params", () => {
    assert.deepEqual(
      actionReferencedLinkIds({
        condition: "q_fever == True",
        instructions: [
          {
            params: {
              message: '{{ f"temp {q_temp}" }}',
              other: "{{ q_note }}",
              literal: "q_ignored",
            },
          },
        ],
      }).sort(),
      ["fever", "note", "temp"],
    );
  });

  it("identifies identifier-safe link ids", () => {
    assert.equal(isIdentifierSafeLinkId("fever_1"), true);
    assert.equal(isIdentifierSafeLinkId("123"), true);
    assert.equal(isIdentifierSafeLinkId("Q-abc12345"), false);
    assert.equal(isIdentifierSafeLinkId("has space"), false);
    assert.equal(isIdentifierSafeLinkId(""), false);
    assert.equal(linkIdOfRef("q_fever"), "fever");
    assert.equal(linkIdOfRef("patient.age"), undefined);
  });
});

describe("remapping", () => {
  const map = new Map([
    ["fever", "Q-new1"],
    ["temp", "Q-new2"],
  ]);

  it("rewrites only q_ names, leaving literals and unknown names alone", () => {
    assert.equal(
      remapQuestionRefs(
        'q_fever == "q_fever" and q_temp > 1 and q_other == 2',
        map,
      ),
      'q_Q-new1 == "q_fever" and q_Q-new2 > 1 and q_other == 2',
    );
  });

  it("follows the map through conditions and templated params of every action", () => {
    const [action] = remapActionLinkIds(
      [
        {
          condition: "q_fever == True",
          instructions: [
            {
              slug: "logging",
              context: "self",
              params: {
                message: '{{ f"temp {q_temp}" }}',
                plain: "q_temp stays",
                count: 3,
              },
            },
          ],
        },
      ],
      map,
    );
    assert.equal(action.condition, "q_Q-new1 == True");
    assert.deepEqual(action.instructions[0].params, {
      message: '{{ f"temp {q_Q-new2}" }}',
      plain: "q_temp stays",
      count: 3,
    });
  });
});

