/**
 * What an action may refer to: the questionnaire's own answers and the
 * context values the backend registry exposes from the submission root.
 * Pure — the editor components and the save rules both read from here.
 */
import { ActionContextField } from "@/types/questionnaire/actions";
import { Question, QuestionType } from "@/types/questionnaire/question";

import { NON_RESPONSE_TYPES } from "./saveValidation";
import {
  ActionRuleOperator,
  isIdentifierSafeLinkId,
  linkIdOfRef,
  questionRef,
} from "./actionExpression";

/** How the backend's cleaned answer for a question compares — decides the
 *  operator set, the value control, and whether the answer is a scalar or
 *  a `{value, coding|unit}` record (see `_clean_result_value` in
 *  `care/emr/resources/questionnaire/utils.py`). */
export type AnswerShape =
  | "boolean"
  | "number"
  | "choice"
  | "choice_multi"
  | "text";

export type UnusableReason = "link_id" | "type" | "coded_multi";

export interface QuestionVariable {
  ref: string;
  question: Question;
  shape: AnswerShape;
  /** Present when the question cannot be referenced from a condition. */
  unusable?: UnusableReason;
}

/** A value the registry can resolve from the root — `patient.age`. */
export interface ContextValueVariable {
  ref: string;
  /** Path segments for display (`["patient", "age"]`). */
  segments: string[];
  /** The context type that owns the leaf (`Patient`). */
  ownerContextType: string;
}

/** A context an instruction can be applied to — `self` (the submission) or
 *  a typed neighbour reached through the field graph (`patient`). */
export interface ContextPathOption {
  path: string;
  contextType: string;
}

export const SELF_CONTEXT_PATH = "self";

/** The registry lists fields once per context map they sit in — the same
 *  (context, field) pair can come back twice. */
export function dedupeContextFields(
  fields: ActionContextField[],
): ActionContextField[] {
  const seen = new Set<string>();
  return fields.filter((field) => {
    const key = `${field.context_type}�${field.field}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

const MAX_CONTEXT_DEPTH = 3;

/**
 * Every typed context reachable from `rootType` by following edge fields
 * (`target_context_type`), root first. Bounded by depth and by not
 * re-entering a context type already on the path, so a cyclic registry
 * cannot loop. Dynamic fields are skipped: they resolve arbitrary names at
 * run time and describe nothing statically.
 */
export function reachableContextPaths(
  rootType: string,
  fields: ActionContextField[],
): ContextPathOption[] {
  const result: ContextPathOption[] = [
    { path: SELF_CONTEXT_PATH, contextType: rootType },
  ];
  const walk = (
    contextType: string,
    path: string,
    chain: ReadonlySet<string>,
    depth: number,
  ) => {
    if (depth >= MAX_CONTEXT_DEPTH) return;
    for (const field of fields) {
      if (
        field.context_type !== contextType ||
        field.evaluation === "dynamic" ||
        !field.target_context_type ||
        chain.has(field.target_context_type)
      ) {
        continue;
      }
      const childPath =
        path === SELF_CONTEXT_PATH ? field.field : `${path}.${field.field}`;
      result.push({ path: childPath, contextType: field.target_context_type });
      walk(
        field.target_context_type,
        childPath,
        new Set([...chain, field.target_context_type]),
        depth + 1,
      );
    }
  };
  walk(rootType, SELF_CONTEXT_PATH, new Set([rootType]), 0);
  return result;
}

/** Every leaf value reachable from the root — what a condition row's
 *  "field" picker offers beside the questionnaire's answers. */
export function reachableContextValues(
  rootType: string,
  fields: ActionContextField[],
): ContextValueVariable[] {
  const values: ContextValueVariable[] = [];
  for (const context of reachableContextPaths(rootType, fields)) {
    for (const field of fields) {
      if (
        field.context_type !== context.contextType ||
        field.evaluation === "dynamic" ||
        field.target_context_type
      ) {
        continue;
      }
      const segments =
        context.path === SELF_CONTEXT_PATH
          ? [field.field]
          : [...context.path.split("."), field.field];
      values.push({
        ref: segments.join("."),
        segments,
        ownerContextType: context.contextType,
      });
    }
  }
  return values;
}

const NUMBER_TYPES: QuestionType[] = ["integer", "decimal", "quantity"];

/** Whether the cleaned answer is a `{value, …}` record rather than a bare
 *  scalar: quantities always carry a unit, numbers do when the question
 *  fixes one, and choice answers do when their options are coded. */
function answerIsRecord(question: Question): boolean {
  if (question.type === "quantity") return true;
  if (
    (question.type === "integer" || question.type === "decimal") &&
    question.unit
  ) {
    return true;
  }
  if (question.type === "choice") {
    return (
      !!question.answer_value_set ||
      (question.answer_option ?? []).some((option) => option.code)
    );
  }
  return false;
}

export function answerShapeOf(question: Question): AnswerShape {
  if (question.type === "boolean") return "boolean";
  if (NUMBER_TYPES.includes(question.type)) return "number";
  if (question.type === "choice") {
    return question.repeats ? "choice_multi" : "choice";
  }
  return "text";
}

/**
 * The questionnaire's answers as condition variables, in tree order.
 * Groups, display blocks and structured questions never produce a `q_`
 * value; hyphenated link ids cannot be spelled as a Python name; and a
 * coded multi-select cleans to a list of records that `in` cannot search.
 * Those stay in the list, marked, so the picker can explain rather than
 * silently omit them.
 */
export function questionVariables(questions: Question[]): QuestionVariable[] {
  const variables: QuestionVariable[] = [];
  const walk = (list: Question[]) => {
    for (const question of list) {
      const shape = answerShapeOf(question);
      const record = answerIsRecord(question);
      const ref = record
        ? `${questionRef(question.link_id)}.value`
        : questionRef(question.link_id);
      let unusable: UnusableReason | undefined;
      if (
        NON_RESPONSE_TYPES.includes(question.type) ||
        question.type === "structured"
      ) {
        unusable = "type";
      } else if (!isIdentifierSafeLinkId(question.link_id)) {
        unusable = "link_id";
      } else if (shape === "choice_multi" && record) {
        unusable = "coded_multi";
      }
      variables.push({ ref, question, shape, unusable });
      walk(question.questions ?? []);
    }
  };
  walk(questions);
  return variables;
}

/** The question a rule's ref points at, if any. */
export function questionOfRef(
  ref: string,
  variables: QuestionVariable[],
): QuestionVariable | undefined {
  const linkId = linkIdOfRef(ref);
  if (linkId === undefined) return undefined;
  return variables.find((variable) => variable.question.link_id === linkId);
}

const OPERATORS_BY_SHAPE: Record<AnswerShape, readonly ActionRuleOperator[]> =
  {
    boolean: ["==", "!="],
    number: ["==", "!=", ">", ">=", "<", "<="],
    choice: ["==", "!="],
    choice_multi: ["in", "not in"],
    text: ["==", "!="],
  };

/** Context values carry no type in the registry — every comparison stays
 *  on offer and the value is typed by what the author enters. */
const CONTEXT_OPERATORS: readonly ActionRuleOperator[] = [
  "==",
  "!=",
  ">",
  ">=",
  "<",
  "<=",
];

export function operatorsFor(
  shape: AnswerShape | undefined,
): readonly ActionRuleOperator[] {
  return shape ? OPERATORS_BY_SHAPE[shape] : CONTEXT_OPERATORS;
}

/**
 * Save-time rules for questionnaire actions — the counterpart of
 * `saveValidation.ts` for the question tree. Each rule names the first
 * action it fails on; the studio blocks Save until the list is empty.
 *
 * The backend only rejects an unknown instruction slug and missing
 * `condition`/`context` fields at save time; a bad expression, a missing
 * required param or a reference to a deleted question would otherwise sail
 * through the PUT and break every SUBMISSION of the questionnaire instead.
 */
import {
  ActionInstructionDefinition,
  QuestionnaireAction,
} from "@/types/questionnaire/actions";
import { Question } from "@/types/questionnaire/question";

import { actionReferencedLinkIds } from "./actionExpression";

export interface ActionIssue {
  /** Index into the questionnaire's `actions` array. */
  index: number;
  messageKey: string;
}

export interface ActionCheckContext {
  linkIds: ReadonlySet<string>;
  /** Undefined until the registry has loaded — the slug rules stand down
   *  rather than flag every action as unknown while the request is in
   *  flight. */
  instructions?: ActionInstructionDefinition[];
}

interface ActionRule {
  predicate: (
    action: QuestionnaireAction,
    context: ActionCheckContext,
  ) => boolean;
  messageKey: string;
}

function isBlank(value: unknown): boolean {
  return (
    value === undefined ||
    value === null ||
    (typeof value === "string" && value.trim() === "")
  );
}

const ACTION_RULES: ActionRule[] = [
  {
    predicate: (action) => action.condition.trim() === "",
    messageKey: "action_issue_condition_empty",
  },
  {
    predicate: (action) => action.instructions.length === 0,
    messageKey: "action_issue_no_instructions",
  },
  {
    predicate: (action) =>
      action.instructions.some((instruction) => !instruction.slug),
    messageKey: "action_issue_instruction_missing",
  },
  {
    predicate: (action, { instructions }) =>
      !!instructions &&
      action.instructions.some(
        (instruction) =>
          instruction.slug &&
          !instructions.some(
            (definition) => definition.slug === instruction.slug,
          ),
      ),
    messageKey: "action_issue_instruction_unknown",
  },
  {
    predicate: (action) =>
      action.instructions.some((instruction) => !instruction.context),
    messageKey: "action_issue_context_missing",
  },
  {
    predicate: (action, { instructions }) =>
      !!instructions &&
      action.instructions.some((instruction) => {
        const definition = instructions.find(
          (candidate) => candidate.slug === instruction.slug,
        );
        return (definition?.input_schema.required ?? []).some((name) =>
          isBlank(instruction.params[name]),
        );
      }),
    messageKey: "action_issue_param_required",
  },
  {
    predicate: (action, { linkIds }) =>
      actionReferencedLinkIds(action).some((linkId) => !linkIds.has(linkId)),
    messageKey: "action_issue_unknown_question",
  },
];

export function collectLinkIds(questions: Question[]): Set<string> {
  const linkIds = new Set<string>();
  const walk = (list: Question[]) => {
    for (const question of list) {
      linkIds.add(question.link_id);
      walk(question.questions ?? []);
    }
  };
  walk(questions);
  return linkIds;
}

/** The first failing rule per action, in action order. */
export function findActionIssues(
  actions: QuestionnaireAction[],
  context: ActionCheckContext,
): ActionIssue[] {
  const issues: ActionIssue[] = [];
  actions.forEach((action, index) => {
    const failing = ACTION_RULES.find((rule) =>
      rule.predicate(action, context),
    );
    if (failing) issues.push({ index, messageKey: failing.messageKey });
  });
  return issues;
}

import { useQuery } from "@tanstack/react-query";

import { actionRegistryKeys } from "@/components/QuestionnaireV2/queryKeys";

import actionApi from "@/types/questionnaire/actionApi";
import {
  ActionContextField,
  ActionInstructionDefinition,
} from "@/types/questionnaire/actions";
import query from "@/Utils/request/query";

import { dedupeContextFields } from "./actionVariables";

/** Registries are module-level on the backend — they change on deploy,
 *  not per request. */
const REGISTRY_STALE_TIME = 10 * 60 * 1000;

export interface ActionRegistry {
  /** Undefined while loading or after a failure — validation rules that
   *  need the registry stand down on undefined (see `actionValidation`). */
  instructions: ActionInstructionDefinition[] | undefined;
  fields: ActionContextField[];
  isLoading: boolean;
  isError: boolean;
}

/** What the backend can run (`instructions`) and what a condition may read
 *  (`fields`), fetched once per session. */
export function useActionRegistry(): ActionRegistry {
  const instructions = useQuery({
    queryKey: actionRegistryKeys.instructions(),
    queryFn: query(actionApi.instructions),
    staleTime: REGISTRY_STALE_TIME,
    select: (data) => data.instructions,
  });
  const fields = useQuery({
    queryKey: actionRegistryKeys.fields(),
    queryFn: query(actionApi.fields),
    staleTime: REGISTRY_STALE_TIME,
    select: (data) => dedupeContextFields(data.fields),
  });
  return {
    instructions: instructions.data,
    fields: fields.data ?? [],
    isLoading: instructions.isLoading || fields.isLoading,
    isError: instructions.isError || fields.isError,
  };
}

