import type { TFunction } from "i18next";

import type { ActionRuleOperator } from "@/components/QuestionnaireV2/builder/actionExpression";
import {
  ContextPathOption,
  ContextValueVariable,
  SELF_CONTEXT_PATH,
} from "@/components/QuestionnaireV2/builder/actionVariables";

import type { Question } from "@/types/questionnaire/question";

/** `send_sms` → "Send sms": registry slugs and field names are code
 *  identifiers with no display strings of their own. */
export function humanize(identifier: string): string {
  const words = identifier.replace(/[_-]+/g, " ").trim();
  return words ? words[0].toUpperCase() + words.slice(1) : identifier;
}

const OPERATOR_LABEL_KEYS: Record<ActionRuleOperator, string> = {
  "==": "equals",
  "!=": "not_equals",
  ">": "greater",
  ">=": "greater_or_equals",
  "<": "less",
  "<=": "less_or_equals",
  in: "action_operator_contains",
  "not in": "action_operator_not_contains",
};

export function operatorLabel(operator: ActionRuleOperator, t: TFunction) {
  return t(OPERATOR_LABEL_KEYS[operator]);
}

export function questionLabel(question: Question, t: TFunction): string {
  return question.text || t("untitled_question");
}

/** "Patient › Age" */
export function contextValueLabel(variable: ContextValueVariable): string {
  return variable.segments.map(humanize).join(" › ");
}

/** "This submission" for the root, otherwise the typed neighbour's name. */
export function contextPathLabel(
  option: ContextPathOption,
  t: TFunction,
): string {
  if (option.path === SELF_CONTEXT_PATH) return t("action_context_self");
  return option.path.split(".").map(humanize).join(" › ");
}

import { Variable, X } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";

import {
  compileTemplate,
  parseTemplate,
} from "@/components/QuestionnaireV2/builder/actionExpression";
import {
  ContextValueVariable,
  QuestionVariable,
  questionOfRef,
} from "@/components/QuestionnaireV2/builder/actionVariables";

import { contextValueLabel, questionLabel } from "./labels";

export interface ActionVariableSources {
  questions: QuestionVariable[];
  contextValues: ContextValueVariable[];
}

interface ParamValueInputProps {
  id: string;
  kind: "string" | "number";
  value: unknown;
  onChange: (value: unknown) => void;
  sources: ActionVariableSources;
  "aria-label": string;
}

/** The "Use a value from…" menu: every usable answer, every context value,
 *  and the custom-expression escape hatch. */
function VariableSourceMenu({
  sources,
  onPick,
}: {
  sources: ActionVariableSources;
  onPick: (value: string) => void;
}) {
  const { t } = useTranslation();
  const questions = sources.questions.filter((entry) => !entry.unusable);
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          type="button"
          variant="outline"
          size="icon"
          className="shrink-0"
          aria-label={t("action_param_use_value")}
        >
          <Variable className="size-4" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="max-h-80 w-64 overflow-y-auto">
        {questions.length > 0 && (
          <DropdownMenuGroup>
            <DropdownMenuLabel>{t("action_field_group_answers")}</DropdownMenuLabel>
            {questions.map((entry) => (
              <DropdownMenuItem
                key={entry.question.id}
                onSelect={() => onPick(compileTemplate(entry.ref))}
              >
                <span className="truncate">{questionLabel(entry.question, t)}</span>
              </DropdownMenuItem>
            ))}
          </DropdownMenuGroup>
        )}
        {sources.contextValues.length > 0 && (
          <DropdownMenuGroup>
            <DropdownMenuLabel>{t("action_field_group_context")}</DropdownMenuLabel>
            {sources.contextValues.map((entry) => (
              <DropdownMenuItem
                key={entry.ref}
                onSelect={() => onPick(compileTemplate(entry.ref))}
              >
                {contextValueLabel(entry)}
              </DropdownMenuItem>
            ))}
          </DropdownMenuGroup>
        )}
        {(questions.length > 0 || sources.contextValues.length > 0) && (
          <DropdownMenuSeparator />
        )}
        <DropdownMenuItem onSelect={() => onPick("{{  }}")}>
          {t("action_param_custom_expression")}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/** Number entry that commits only what parses — a controlled number input
 *  fed straight from the stored value would rewrite "0." to "0"
 *  mid-keystroke (see `NumericAnswerInput` in VisibilityConditionsCard). */
function NumberLiteralInput({
  id,
  value,
  onChange,
  ...rest
}: {
  id: string;
  value: unknown;
  onChange: (value: number | undefined) => void;
  "aria-label": string;
}) {
  const [buffer, setBuffer] = useState<string | null>(null);
  return (
    <Input
      id={id}
      type="number"
      value={buffer ?? (typeof value === "number" ? String(value) : "")}
      onChange={(e) => {
        setBuffer(e.target.value);
        if (e.target.value === "") onChange(undefined);
        else if (!Number.isNaN(e.target.valueAsNumber)) {
          onChange(e.target.valueAsNumber);
        }
      }}
      onBlur={() => setBuffer(null)}
      {...rest}
    />
  );
}

/**
 * One string/number instruction param. The stored value is either a plain
 * literal, or a `{{ … }}` template the backend evaluates at run time: a
 * picked variable renders as a labelled chip, a custom expression as a
 * monospace text field. Either way one click returns to a fixed value.
 */
export function ParamValueInput({
  id,
  kind,
  value,
  onChange,
  sources,
  "aria-label": ariaLabel,
}: ParamValueInputProps) {
  const { t } = useTranslation();
  const template = parseTemplate(value);

  if (template?.kind === "ref") {
    const question = questionOfRef(template.ref, sources.questions);
    const contextValue = sources.contextValues.find(
      (entry) => entry.ref === template.ref,
    );
    const label = question
      ? t("action_param_answer_of", {
          question: questionLabel(question.question, t),
        })
      : contextValue
        ? contextValueLabel(contextValue)
        : template.ref;
    return (
      <div className="flex items-center gap-2">
        <div
          id={id}
          className="flex h-9 min-w-0 flex-1 items-center gap-2 rounded-md border border-dashed border-primary-300 bg-primary-50 px-2.5 text-sm text-primary-900"
        >
          <Variable aria-hidden className="size-4 shrink-0" />
          <span className="truncate">{label}</span>
        </div>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="shrink-0"
          aria-label={t("action_param_clear_source")}
          onClick={() => onChange(kind === "number" ? undefined : "")}
        >
          <X className="size-4" />
        </Button>
      </div>
    );
  }

  if (template?.kind === "expression") {
    return (
      <div className="space-y-1">
        <div className="flex items-center gap-2">
          <Input
            id={id}
            aria-label={ariaLabel}
            className="font-mono text-xs"
            value={template.expression}
            placeholder='f"…{q_link_id}…"'
            onChange={(e) => onChange(`{{ ${e.target.value} }}`)}
          />
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="shrink-0"
            aria-label={t("action_param_clear_source")}
            onClick={() => onChange(kind === "number" ? undefined : "")}
          >
            <X className="size-4" />
          </Button>
        </div>
        <p className="text-xs text-gray-500">{t("action_expression_help")}</p>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2">
      {kind === "number" ? (
        <NumberLiteralInput
          id={id}
          value={value}
          onChange={onChange}
          aria-label={ariaLabel}
        />
      ) : (
        <Input
          id={id}
          aria-label={ariaLabel}
          value={typeof value === "string" ? value : ""}
          onChange={(e) => onChange(e.target.value)}
        />
      )}
      <VariableSourceMenu sources={sources} onPick={onChange} />
    </div>
  );
}

import { Trash2 } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";

import {
  ContextPathOption,
  SELF_CONTEXT_PATH,
} from "@/components/QuestionnaireV2/builder/actionVariables";

import {
  ActionInstructionDefinition,
  ActionParamSchema,
  QuestionnaireActionInstruction,
} from "@/types/questionnaire/actions";

import { ActionVariableSources, ParamValueInput } from "./ParamValueInput";
import { contextPathLabel, humanize } from "./labels";

type ParamKind = "string" | "number" | "boolean" | "enum" | "json";

/** Pydantic renders `str | None` as `anyOf` — the first non-null branch is
 *  the one the author fills in. */
function resolveSchema(schema: ActionParamSchema): ActionParamSchema {
  if (!schema.anyOf) return schema;
  return (
    schema.anyOf.find((branch) => branch.type !== "null") ?? schema.anyOf[0]
  );
}

function paramKindOf(schema: ActionParamSchema): ParamKind {
  const resolved = resolveSchema(schema);
  const type = Array.isArray(resolved.type)
    ? resolved.type.find((entry) => entry !== "null")
    : resolved.type;
  if (resolved.enum && resolved.enum.every((v) => typeof v === "string")) {
    return "enum";
  }
  switch (type) {
    case "string":
      return "string";
    case "integer":
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    default:
      return "json";
  }
}

/** The params a freshly picked instruction starts with — schema defaults
 *  only, so a required param without one stays blank and the save rule
 *  flags it. */
export function defaultParams(
  definition: ActionInstructionDefinition,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(definition.input_schema.properties ?? {})
      .filter(([, schema]) => schema.default !== undefined)
      .map(([name, schema]) => [name, schema.default]),
  );
}

/** The context path a definition is most naturally applied to: the
 *  reachable path whose type matches its declared context, else the
 *  submission itself. */
export function defaultContextPath(
  definition: ActionInstructionDefinition | undefined,
  contextPaths: ContextPathOption[],
): string {
  const match = definition
    ? contextPaths.find((option) => option.contextType === definition.context)
    : undefined;
  return match?.path ?? SELF_CONTEXT_PATH;
}

/** Anything the typed controls cannot express is edited as JSON text —
 *  committed on blur, and kept as text while it does not parse. */
function JsonParamInput({
  id,
  value,
  onChange,
  "aria-label": ariaLabel,
}: {
  id: string;
  value: unknown;
  onChange: (value: unknown) => void;
  "aria-label": string;
}) {
  const { t } = useTranslation();
  const [text, setText] = useState(() =>
    value === undefined ? "" : JSON.stringify(value, null, 2),
  );
  const [invalid, setInvalid] = useState(false);
  return (
    <div className="space-y-1">
      <Textarea
        id={id}
        aria-label={ariaLabel}
        aria-invalid={invalid}
        className="font-mono text-xs"
        rows={3}
        value={text}
        onChange={(e) => setText(e.target.value)}
        onBlur={() => {
          if (text.trim() === "") {
            setInvalid(false);
            onChange(undefined);
            return;
          }
          try {
            onChange(JSON.parse(text));
            setInvalid(false);
          } catch {
            setInvalid(true);
          }
        }}
      />
      {invalid && (
        <p className="text-xs text-red-600">{t("action_param_json_invalid")}</p>
      )}
    </div>
  );
}

interface InstructionEditorProps {
  /** Stable per-instruction DOM id prefix. */
  idPrefix: string;
  instruction: QuestionnaireActionInstruction;
  definitions: ActionInstructionDefinition[] | undefined;
  contextPaths: ContextPathOption[];
  sources: ActionVariableSources;
  onChange: (instruction: QuestionnaireActionInstruction) => void;
  onRemove: () => void;
}

/**
 * One "Then" step: which registered instruction runs, the inputs its
 * `input_schema` declares, and which context it is applied to.
 */
export function InstructionEditor({
  idPrefix,
  instruction,
  definitions,
  contextPaths,
  sources,
  onChange,
  onRemove,
}: InstructionEditorProps) {
  const { t } = useTranslation();
  const definition = definitions?.find(
    (candidate) => candidate.slug === instruction.slug,
  );
  // A saved slug the registry no longer serves — kept visible (and
  // flagged) rather than blanked, so the author sees what was there.
  const unknownSlug =
    !!definitions && !!instruction.slug && !definition
      ? instruction.slug
      : undefined;
  const contextKnown = contextPaths.some(
    (option) => option.path === instruction.context,
  );
  const properties = Object.entries(definition?.input_schema.properties ?? {});
  const required = new Set(definition?.input_schema.required ?? []);

  const setParam = (name: string, value: unknown) => {
    const params = { ...instruction.params };
    if (value === undefined) delete params[name];
    else params[name] = value;
    onChange({ ...instruction, params });
  };

  return (
    <div className="space-y-3 rounded-md bg-gray-50 p-3">
      <div className="flex items-center justify-between gap-2">
        <span className="text-sm font-medium text-gray-900">
          {t("action_instruction")}
        </span>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="size-6"
          onClick={onRemove}
          aria-label={t("action_remove_instruction")}
        >
          <Trash2 className="size-4" />
        </Button>
      </div>

      <Select
        value={instruction.slug || undefined}
        onValueChange={(slug) => {
          const next = definitions?.find((candidate) => candidate.slug === slug);
          onChange({
            slug,
            params: next ? defaultParams(next) : {},
            context: defaultContextPath(next, contextPaths),
          });
        }}
      >
        <SelectTrigger
          className="w-full"
          aria-label={t("action_instruction")}
          aria-invalid={Boolean(unknownSlug)}
        >
          <SelectValue placeholder={t("action_instruction_placeholder")} />
        </SelectTrigger>
        <SelectContent>
          {unknownSlug && (
            <SelectItem value={unknownSlug} disabled className="text-red-600">
              {humanize(unknownSlug)}
            </SelectItem>
          )}
          {(definitions ?? []).map((candidate) => (
            <SelectItem key={candidate.slug} value={candidate.slug}>
              <span className="flex items-center gap-2">
                {humanize(candidate.slug)}
                <Badge variant="secondary" className="font-mono text-[10px]">
                  {candidate.instruction_type}
                </Badge>
              </span>
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      {unknownSlug && (
        <p className="text-xs text-red-600">{t("action_instruction_unknown")}</p>
      )}

      {properties.map(([name, schema]) => {
        const kind = paramKindOf(schema);
        const resolved = resolveSchema(schema);
        const id = `${idPrefix}-param-${name}`;
        const label = schema.title ?? humanize(name);
        const value = instruction.params[name];
        return (
          <div key={name} className="space-y-1.5">
            <Label htmlFor={id} className="text-xs font-medium text-gray-600">
              {label}
              {required.has(name) ? (
                <span className="text-red-600"> *</span>
              ) : (
                <span className="font-normal text-gray-400">
                  {" "}
                  · {t("optional")}
                </span>
              )}
            </Label>
            {schema.description && (
              <p className="text-xs text-gray-500">{schema.description}</p>
            )}
            {kind === "boolean" ? (
              <Switch
                id={id}
                aria-label={label}
                checked={value === true}
                onCheckedChange={(checked) => setParam(name, checked)}
              />
            ) : kind === "enum" ? (
              <Select
                value={typeof value === "string" ? value : undefined}
                onValueChange={(next) => setParam(name, next)}
              >
                <SelectTrigger id={id} className="w-full" aria-label={label}>
                  <SelectValue placeholder={t("select")} />
                </SelectTrigger>
                <SelectContent>
                  {(resolved.enum ?? []).map((option) => (
                    <SelectItem key={String(option)} value={String(option)}>
                      {String(option)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            ) : kind === "json" ? (
              <JsonParamInput
                id={id}
                value={value}
                onChange={(next) => setParam(name, next)}
                aria-label={label}
              />
            ) : (
              <ParamValueInput
                id={id}
                kind={kind}
                value={value}
                onChange={(next) => setParam(name, next)}
                sources={sources}
                aria-label={label}
              />
            )}
          </div>
        );
      })}

      {/* Which object the instruction acts on. Hidden while the submission
          itself is the only option and that is what's stored — showing a
          one-item select would only raise a question it can't answer. */}
      {(contextPaths.length > 1 || !contextKnown) && (
        <div className="space-y-1.5">
          <Label
            htmlFor={`${idPrefix}-context`}
            className="text-xs font-medium text-gray-600"
          >
            {t("action_applies_to")}
          </Label>
          <Select
            value={instruction.context || undefined}
            onValueChange={(context) => onChange({ ...instruction, context })}
          >
            <SelectTrigger
              id={`${idPrefix}-context`}
              className="w-full"
              aria-label={t("action_applies_to")}
              aria-invalid={!contextKnown}
            >
              <SelectValue placeholder={t("select")} />
            </SelectTrigger>
            <SelectContent>
              {!contextKnown && instruction.context && (
                <SelectItem
                  value={instruction.context}
                  disabled
                  className="text-red-600"
                >
                  {instruction.context}
                </SelectItem>
              )}
              {contextPaths.map((option) => (
                <SelectItem key={option.path} value={option.path}>
                  {contextPathLabel(option, t)}
                  {definition && option.contextType === definition.context && (
                    <span className="ml-2 text-xs text-gray-400">
                      · {t("action_context_matches")}
                    </span>
                  )}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      )}
    </div>
  );
}

import { Plus, TriangleAlert, Trash2 } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

import { ChoiceChip } from "@/components/QuestionnaireV2/shared/ChoiceChip";

import {
  ActionRule,
  ActionRuleBehavior,
  ActionRuleOperator,
  ActionRuleValue,
  compileCondition,
  parseCondition,
} from "@/components/QuestionnaireV2/builder/actionExpression";
import {
  AnswerShape,
  ContextValueVariable,
  QuestionVariable,
  operatorsFor,
  questionOfRef,
} from "@/components/QuestionnaireV2/builder/actionVariables";

import { Question } from "@/types/questionnaire/question";

import { contextValueLabel, operatorLabel, questionLabel } from "./labels";

interface ActionConditionEditorProps {
  /** Stable DOM id prefix for this action's controls. */
  idPrefix: string;
  condition: string;
  onChange: (condition: string) => void;
  questions: QuestionVariable[];
  contextValues: ContextValueVariable[];
}

const NUMERIC_TEXT = /^-?\d+(\.\d+)?$/;

/** The value a fresh rule starts with, so every row compiles from the
 *  moment it exists — a half-built row would have no valid expression to
 *  persist. */
function defaultValue(
  shape: AnswerShape | undefined,
  question: Question | undefined,
): ActionRuleValue {
  switch (shape) {
    case "boolean":
      return true;
    case "number":
      return 0;
    case "choice":
    case "choice_multi":
      return question?.answer_option?.[0]?.value ?? "";
    default:
      return "";
  }
}

/** Number entry that commits only what parses (see `NumericAnswerInput`
 *  in VisibilityConditionsCard for why a bare controlled input won't do). */
function NumericRuleValue({
  value,
  onChange,
  "aria-label": ariaLabel,
}: {
  value: ActionRuleValue;
  onChange: (next: number) => void;
  "aria-label": string;
}) {
  const [buffer, setBuffer] = useState<string | null>(null);
  return (
    <Input
      type="number"
      aria-label={ariaLabel}
      value={buffer ?? String(value ?? "")}
      onChange={(e) => {
        setBuffer(e.target.value);
        if (e.target.value !== "" && !Number.isNaN(e.target.valueAsNumber)) {
          onChange(e.target.valueAsNumber);
        }
      }}
      onBlur={() => setBuffer(null)}
    />
  );
}

/**
 * The "When" half of an action. Two faces over one stored string: the rule
 * builder (field / operator / value rows joined by AND or OR) for the
 * canonical subset `actionExpression` round-trips, and a plain expression
 * editor for everything else. A stored condition the builder cannot read
 * opens in expression mode; the way back is offered only once the text
 * parses again.
 */
export function ActionConditionEditor({
  idPrefix,
  condition,
  onChange,
  questions,
  contextValues,
}: ActionConditionEditorProps) {
  const { t } = useTranslation();
  const parsed = parseCondition(condition);
  const [wantsExpression, setWantsExpression] = useState(false);
  const expressionMode = wantsExpression || !parsed;

  const usableQuestions = questions.filter((entry) => !entry.unusable);
  const canAddRule = usableQuestions.length > 0 || contextValues.length > 0;

  const update = (rules: ActionRule[], behavior: ActionRuleBehavior) =>
    onChange(compileCondition(rules, behavior));

  const shapeOf = (ref: string): AnswerShape | undefined =>
    questionOfRef(ref, questions)?.shape;

  const addRule = () => {
    if (!parsed) return;
    const first = usableQuestions[0];
    const ref = first?.ref ?? contextValues[0]?.ref;
    if (!ref) return;
    const shape = first?.shape;
    update(
      [
        ...parsed.rules,
        {
          ref,
          operator: operatorsFor(shape)[0],
          value: defaultValue(shape, first?.question),
        },
      ],
      parsed.behavior,
    );
  };

  const setRule = (index: number, rule: ActionRule) => {
    if (!parsed) return;
    const rules = [...parsed.rules];
    rules[index] = rule;
    update(rules, parsed.behavior);
  };

  const changeRef = (index: number, ref: string) => {
    const target = questionOfRef(ref, questions);
    const shape = target?.shape;
    setRule(index, {
      ref,
      operator: operatorsFor(shape)[0],
      value: defaultValue(shape, target?.question),
    });
  };

  if (expressionMode) {
    return (
      <div className="space-y-2">
        <Textarea
          id={`${idPrefix}-expression`}
          aria-label={t("action_expression")}
          className="font-mono text-xs"
          rows={3}
          value={condition}
          onChange={(e) => onChange(e.target.value)}
        />
        <p className="text-xs text-gray-500">{t("action_expression_help")}</p>
        {!parsed && !wantsExpression && (
          <p className="text-xs text-gray-500">
            {t("action_custom_expression_note")}
          </p>
        )}
        <Button
          type="button"
          variant="link"
          size="sm"
          className="h-auto px-0"
          disabled={!parsed}
          onClick={() => setWantsExpression(false)}
        >
          {t("action_back_to_conditions")}
        </Button>
      </div>
    );
  }

  const { rules, behavior } = parsed;
  // Answering is what puts `q_<link_id>` into the evaluator's namespace: a
  // rule on an optional question that was skipped makes the backend raise
  // and the whole submission fail. Said once per card, not per row.
  const optionalReferenced = rules.some((rule) => {
    const target = questionOfRef(rule.ref, questions);
    return target && !target.question.required;
  });

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap gap-2">
        <ChoiceChip
          control="radio"
          label={t("action_every_submission")}
          checked={rules.length === 0}
          onCheckedChange={() => update([], behavior)}
        />
        <ChoiceChip
          control="radio"
          label={t("action_when_conditions_match")}
          checked={rules.length > 0}
          disabled={!canAddRule}
          onCheckedChange={addRule}
        />
      </div>

      {rules.length === 0 && !canAddRule && (
        <p className="text-xs text-gray-500">
          {t("action_no_fields_available")}
        </p>
      )}

      {rules.length > 1 && (
        <div className="flex flex-wrap gap-2">
          <ChoiceChip
            control="radio"
            label={t("all_conditions_and")}
            checked={behavior === "all"}
            onCheckedChange={() => update(rules, "all")}
          />
          <ChoiceChip
            control="radio"
            label={t("any_condition_or")}
            checked={behavior === "any"}
            onCheckedChange={() => update(rules, "any")}
          />
        </div>
      )}

      <div className="space-y-2">
        {rules.map((rule, index) => {
          const target = questionOfRef(rule.ref, questions);
          const shape = target?.shape;
          const operators = operatorsFor(shape);
          const options = target?.question.answer_option ?? [];
          const rowLabel = t("condition_n", { n: index + 1 });
          return (
            <div key={index}>
              {index > 0 && (
                <div className="relative flex justify-start py-1 pl-6">
                  <span
                    className="absolute left-[1.375rem] top-0 h-full w-px bg-gray-200"
                    aria-hidden
                  />
                  <span className="relative rounded-md border border-gray-200 bg-white px-2 py-0.5 text-xs font-semibold uppercase text-gray-500">
                    {behavior === "all" ? t("and") : t("or")}
                  </span>
                </div>
              )}
              <div className="space-y-2 rounded-md bg-gray-50 p-3">
                <div className="flex items-center justify-between">
                  <span className="text-sm font-medium text-gray-900">
                    {rowLabel}
                  </span>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="size-6"
                    onClick={() =>
                      update(
                        rules.filter((_, i) => i !== index),
                        behavior,
                      )
                    }
                    aria-label={t("delete")}
                  >
                    <Trash2 className="size-4" />
                  </Button>
                </div>

                <div className="grid gap-2 sm:grid-cols-2">
                  <div className="space-y-1 sm:col-span-2">
                    <p className="text-xs text-gray-500">{t("action_field")}</p>
                    <Select
                      value={rule.ref}
                      onValueChange={(ref) => changeRef(index, ref)}
                    >
                      <SelectTrigger
                        className="w-full"
                        aria-label={`${rowLabel} ${t("action_field")}`}
                        aria-invalid={Boolean(target?.unusable)}
                      >
                        <SelectValue placeholder={t("select")} />
                      </SelectTrigger>
                      <SelectContent>
                        {/* A ref that names nothing current (deleted
                            question, registry change) stays visible so the
                            author can see what to fix. */}
                        {!target &&
                          !contextValues.some((v) => v.ref === rule.ref) && (
                            <SelectItem
                              value={rule.ref}
                              disabled
                              className="text-red-600"
                            >
                              {rule.ref}
                            </SelectItem>
                          )}
                        {questions.length > 0 && (
                          <SelectGroup>
                            <SelectLabel>
                              {t("action_field_group_answers")}
                            </SelectLabel>
                            {questions.map((entry) => (
                              <SelectItem
                                key={entry.question.id}
                                value={entry.ref}
                                disabled={Boolean(entry.unusable)}
                              >
                                {questionLabel(entry.question, t)}
                                {entry.unusable && (
                                  <span className="ml-1 text-xs text-gray-400">
                                    · {t(`action_unusable_${entry.unusable}`)}
                                  </span>
                                )}
                              </SelectItem>
                            ))}
                          </SelectGroup>
                        )}
                        {contextValues.length > 0 && (
                          <SelectGroup>
                            <SelectLabel>
                              {t("action_field_group_context")}
                            </SelectLabel>
                            {contextValues.map((entry) => (
                              <SelectItem key={entry.ref} value={entry.ref}>
                                {contextValueLabel(entry)}
                              </SelectItem>
                            ))}
                          </SelectGroup>
                        )}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-1">
                    <p className="text-xs text-gray-500">{t("operator")}</p>
                    <Select
                      value={rule.operator}
                      onValueChange={(value) => {
                        const operator = operators.find((o) => o === value);
                        if (operator) setRule(index, { ...rule, operator });
                      }}
                    >
                      <SelectTrigger
                        className="w-full"
                        aria-label={`${rowLabel} ${t("operator")}`}
                      >
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {operators.map((operator: ActionRuleOperator) => (
                          <SelectItem key={operator} value={operator}>
                            {operatorLabel(operator, t)}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-1">
                    <p className="text-xs text-gray-500">{t("action_value")}</p>
                    {shape === "boolean" ? (
                      <Select
                        value={rule.value === true ? "true" : "false"}
                        onValueChange={(value) =>
                          setRule(index, { ...rule, value: value === "true" })
                        }
                      >
                        <SelectTrigger
                          className="w-full"
                          aria-label={`${rowLabel} ${t("action_value")}`}
                        >
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="true">{t("yes")}</SelectItem>
                          <SelectItem value="false">{t("no")}</SelectItem>
                        </SelectContent>
                      </Select>
                    ) : shape === "number" ? (
                      <NumericRuleValue
                        value={rule.value}
                        onChange={(value) => setRule(index, { ...rule, value })}
                        aria-label={`${rowLabel} ${t("action_value")}`}
                      />
                    ) : (shape === "choice" || shape === "choice_multi") &&
                      options.length > 0 ? (
                      <Select
                        value={String(rule.value)}
                        onValueChange={(value) =>
                          setRule(index, { ...rule, value })
                        }
                      >
                        <SelectTrigger
                          className="w-full"
                          aria-label={`${rowLabel} ${t("action_value")}`}
                        >
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {options.map((option) => (
                            <SelectItem key={option.value} value={option.value}>
                              {option.display || option.value}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    ) : (
                      <Input
                        aria-label={`${rowLabel} ${t("action_value")}`}
                        value={String(rule.value ?? "")}
                        onChange={(e) => {
                          const text = e.target.value;
                          // Context values carry no type: a numeric entry
                          // compares as a number, anything else as text.
                          const value =
                            !shape && NUMERIC_TEXT.test(text)
                              ? Number(text)
                              : text;
                          setRule(index, { ...rule, value });
                        }}
                      />
                    )}
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {optionalReferenced && (
        <p className="flex items-start gap-2 rounded-md border border-amber-200 bg-amber-50 p-2.5 text-xs text-amber-900">
          <TriangleAlert aria-hidden className="mt-0.5 size-3.5 shrink-0" />
          {t("action_rule_unanswered_hazard")}
        </p>
      )}

      {rules.length > 0 && (
        <div className="flex flex-wrap items-center gap-3">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={addRule}
            disabled={!canAddRule}
          >
            <Plus className="size-4" />
            {t("add_a_condition")}
          </Button>
          <Button
            type="button"
            variant="link"
            size="sm"
            className="h-auto px-0"
            onClick={() => setWantsExpression(true)}
          >
            {t("action_edit_as_expression")}
          </Button>
        </div>
      )}
      {rules.length === 0 && (
        <Button
          type="button"
          variant="link"
          size="sm"
          className="h-auto px-0"
          onClick={() => setWantsExpression(true)}
        >
          {t("action_edit_as_expression")}
        </Button>
      )}
    </div>
  );
}

import type { TFunction } from "i18next";

import { parseCondition } from "@/components/QuestionnaireV2/builder/actionExpression";
import {
  ContextValueVariable,
  QuestionVariable,
  questionOfRef,
} from "@/components/QuestionnaireV2/builder/actionVariables";
import {
  contextValueLabel,
  humanize,
  operatorLabel,
  questionLabel,
} from "@/components/QuestionnaireV2/builder/actions/labels";

import type { QuestionnaireAction } from "@/types/questionnaire/actions";

/**
 * The "In plain words" line under an action card — the counterpart of
 * `conditionSummary.ts` for visibility rules. Reads the condition through
 * the same parser the editor uses; a custom expression is quoted verbatim.
 */
export function actionPlainWords(
  action: QuestionnaireAction,
  questions: QuestionVariable[],
  contextValues: ContextValueVariable[],
  t: TFunction,
): string {
  const parsed = parseCondition(action.condition);
  let when: string;
  if (!parsed) {
    when = t("action_plain_when_expression", {
      expression: action.condition.trim(),
    });
  } else if (parsed.rules.length === 0) {
    when = t("action_plain_every_submission");
  } else {
    const joiner =
      parsed.behavior === "any"
