      const contextValue = contextValues.find((v) => v.ref === rule.ref);
      const field = target
        ? questionLabel(target.question, t)
        : contextValue
          ? contextValueLabel(contextValue)
          : rule.ref;
      const value =
        typeof rule.value === "boolean"
          ? t(rule.value ? "yes" : "no")
