import type { ActionOutcome } from "@/types/questionnaire/actions";

/**
 * What the backend's questionnaire actions reported back on a successful
 * submission — the `_actions` list the submit view appends to its response
 * (`QuestionnaireViewSet.submit`), one entry per instruction that ran, and
 * carried through the batch endpoint as `results[i].data._actions`.
 */

interface BatchResultLike {
  reference_id?: string;
  data?: unknown;
}

function isOutcome(value: unknown): value is ActionOutcome {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as ActionOutcome).slug === "string" &&
    typeof (value as ActionOutcome).instruction_type === "string"
  );
}

/**
 * The outcomes from every questionnaire-submit result in a batch response.
 * `submitReferenceIds` are the reference ids `composeBatch` gave those
 * requests (the questionnaire ids) — structured-type requests to domain
 * APIs and the draft-completion PUT never carry `_actions`.
 */
export function collectActionOutcomes(
  results: BatchResultLike[],
  submitReferenceIds: ReadonlySet<string>,
): ActionOutcome[] {
  const outcomes: ActionOutcome[] = [];
  for (const result of results) {
    if (!result.reference_id || !submitReferenceIds.has(result.reference_id)) {
      continue;
    }
    const actions = (result.data as { _actions?: unknown } | undefined)
      ?._actions;
    if (!Array.isArray(actions)) continue;
    for (const entry of actions) {
      if (isOutcome(entry)) outcomes.push(entry);
    }
  }
  return outcomes;
}

/** The human-readable text an instruction produced, when its `results`
 *  follow the `{message}` convention the shipped instructions use. */
export function outcomeMessage(outcome: ActionOutcome): string | undefined {
  const results = outcome.results;
  if (typeof results === "string") return results;
  if (typeof results === "object" && results !== null) {
    const message = (results as { message?: unknown }).message;
    if (typeof message === "string" && message.trim()) return message;
  }
  return undefined;
}

/**
 * The in-app path a REDIRECT outcome points at, if it is one. Only a
 * same-origin absolute path is honoured: a full URL or a scheme in an
 * instruction's output must not be able to send the clinician off-site.
 */
export function outcomeRedirectPath(outcome: ActionOutcome): string | undefined {
  if (outcome.instruction_type !== "REDIRECT") return undefined;
  const results = outcome.results;
  const candidate =
    typeof results === "string"
      ? results
      : typeof results === "object" && results !== null
        ? (results as { url?: unknown; path?: unknown }).url ??
          (results as { path?: unknown }).path
        : undefined;
  if (typeof candidate !== "string") return undefined;
  return /^\/(?!\/)/.test(candidate) ? candidate : undefined;
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import {
  collectActionOutcomes,
  outcomeMessage,
  outcomeRedirectPath,
} from "./actionOutcomes";

const notify = {
  slug: "logging",
  instruction_type: "NOTIFY",
  results: { message: "fever with temp 39.2" },
};

describe("collectActionOutcomes", () => {
  it("reads _actions only from the questionnaire submit results", () => {
    const outcomes = collectActionOutcomes(
      [
        { reference_id: "qn-1", data: { id: "r1", _actions: [notify] } },
        {
          reference_id: "structured:symptom:q9",
          data: { _actions: [{ ...notify, slug: "not-mine" }] },
        },
        { reference_id: "qn-2", data: { id: "r2" } },
        { reference_id: "qn-3", data: { _actions: "garbage" } },
        { reference_id: "qn-3", data: { _actions: [{ nope: true }, notify] } },
        { data: { _actions: [notify] } },
      ],
      new Set(["qn-1", "qn-2", "qn-3"]),
    );
    assert.deepEqual(outcomes, [notify, notify]);
  });
});

describe("outcomeMessage", () => {
  it("uses the {message} convention or a bare string, else nothing", () => {
    assert.equal(outcomeMessage(notify), "fever with temp 39.2");
    assert.equal(
      outcomeMessage({ ...notify, results: "plain" }),
      "plain",
    );
    assert.equal(outcomeMessage({ ...notify, results: { message: "  " } }), undefined);
    assert.equal(outcomeMessage({ ...notify, results: { other: 1 } }), undefined);
    assert.equal(outcomeMessage({ ...notify, results: null }), undefined);
  });
});

describe("outcomeRedirectPath", () => {
  it("honours only same-origin absolute paths from REDIRECT outcomes", () => {
    const redirect = (results: unknown) => ({
      slug: "go",
      instruction_type: "REDIRECT",
      results,
    });
    assert.equal(
      outcomeRedirectPath(redirect({ url: "/facility/1/patients" })),
      "/facility/1/patients",
    );
    assert.equal(outcomeRedirectPath(redirect({ path: "/x" })), "/x");
    assert.equal(outcomeRedirectPath(redirect("/y?z=1")), "/y?z=1");
    assert.equal(outcomeRedirectPath(redirect({ url: "https://evil.example" })), undefined);
    assert.equal(outcomeRedirectPath(redirect({ url: "//evil.example" })), undefined);
    assert.equal(outcomeRedirectPath(redirect({ url: "javascript:alert(1)" })), undefined);
    assert.equal(outcomeRedirectPath(redirect({ url: "relative" })), undefined);
    assert.equal(outcomeRedirectPath({ ...notify, results: { url: "/x" } }), undefined);
  });
});

