import type { TFunction } from "i18next";

import type { ActionRuleOperator } from "@/components/QuestionnaireV2/shared/actionExpression";
import {
  ContextPathOption,
  ContextValueVariable,
  QuestionVariable,
  SELF_CONTEXT_PATH,
} from "@/components/QuestionnaireV2/builder/actionVariables";

import type { Question } from "@/types/questionnaire/question";

/** What the editors need to name things: the questionnaire's answers, the
 *  registry's context values, and each question's dotted outline number. */
export interface ActionVariableSources {
  questions: QuestionVariable[];
  contextValues: ContextValueVariable[];
  numbers: ReadonlyMap<string, string>;
}

/** `send_sms` → "Send sms": registry slugs and field names are code
 *  identifiers with no display strings of their own. */
export function humanize(identifier: string): string {
  const words = identifier.replace(/[_-]+/g, " ").trim();
  return words ? words[0].toUpperCase() + words.slice(1) : identifier;
}

const OPERATOR_LABEL_KEYS: Record<ActionRuleOperator, string> = {
  "==": "equals",
  "!=": "not_equals",
  ">": "greater",
  ">=": "greater_or_equals",
  "<": "less",
  "<=": "less_or_equals",
  in: "action_operator_contains",
  "not in": "action_operator_not_contains",
};

export function operatorLabel(operator: ActionRuleOperator, t: TFunction) {
  return t(OPERATOR_LABEL_KEYS[operator]);
}

export function questionLabel(question: Question, t: TFunction): string {
  return question.text || t("untitled_question");
}

/** "3.1. Fever?" — numbered like the studio's mobile question select, so
 *  two questions sharing a title stay distinguishable. */
export function numberedQuestionLabel(
  question: Question,
  numbers: ReadonlyMap<string, string>,
  t: TFunction,
): string {
  const number = numbers.get(question.id);
  const label = questionLabel(question, t);
  return number ? `${number} ${label}` : label;
}

/** "Patient › Age" */
export function contextValueLabel(variable: ContextValueVariable): string {
  return variable.segments.map(humanize).join(" › ");
}

/** "This submission" for the root, otherwise the typed neighbour's name. */
export function contextPathLabel(
  option: ContextPathOption,
  t: TFunction,
): string {
  if (option.path === SELF_CONTEXT_PATH) return t("action_context_self");
  return option.path.split(".").map(humanize).join(" › ");
}

/** Plain-language names for registry instructions the UI knows about;
 *  anything else falls back to its humanized slug (never the raw slug). */
const INSTRUCTION_LABEL_KEYS: Record<string, string> = {
  logging: "action_instruction_logging",
};

export function instructionLabel(slug: string, t: TFunction): string {
  const key = INSTRUCTION_LABEL_KEYS[slug];
  return key ? t(key) : humanize(slug);
}

const INSTRUCTION_TYPE_KEYS: Record<string, string> = {
  NOTIFY: "action_type_notify",
  TEXT: "action_type_text",
  PERFORMED: "action_type_performed",
  VALIDATE: "action_type_validate",
  REDIRECT: "action_type_redirect",
};

export function instructionTypeLabel(type: string, t: TFunction): string {
  const key = INSTRUCTION_TYPE_KEYS[type];
  return key ? t(key) : humanize(type.toLowerCase());
}

import { Variable, X } from "lucide-react";
import { Fragment, useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";

import {
  compileMessageTemplate,
  compileTemplate,
  messageToken,
  parseMessageTemplate,
  parseTemplate,
} from "@/components/QuestionnaireV2/shared/actionExpression";

import { questionOfRef } from "@/components/QuestionnaireV2/builder/actionVariables";

import {
  ActionVariableSources,
  contextValueLabel,
  numberedQuestionLabel,
  questionLabel,
} from "./labels";

interface ParamValueInputProps {
  id: string;
  kind: "string" | "number";
  value: unknown;
  onChange: (value: unknown) => void;
  sources: ActionVariableSources;
  "aria-label": string;
}

/** The "Insert an answer…" menu: every usable answer, every context value,
 *  and the custom-expression escape hatch. `onPick` receives the ref. */
function VariableSourceMenu({
  sources,
  onPick,
  onCustomExpression,
}: {
  sources: ActionVariableSources;
  onPick: (ref: string) => void;
  onCustomExpression: () => void;
}) {
  const { t } = useTranslation();
  const questions = sources.questions.filter((entry) => !entry.unusable);
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          type="button"
          variant="outline"
          size="icon"
          className="shrink-0"
          aria-label={t("action_param_insert_value")}
        >
          <Variable className="size-4" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        className="max-h-80 w-64 overflow-y-auto"
      >
        {questions.length > 0 && (
          <DropdownMenuGroup>
            <DropdownMenuLabel>
              {t("action_field_group_answers")}
            </DropdownMenuLabel>
            {questions.map((entry) => (
              <DropdownMenuItem
                key={entry.question.id}
                onSelect={() => onPick(entry.ref)}
              >
                <span className="truncate">
                  {numberedQuestionLabel(entry.question, sources.numbers, t)}
                </span>
              </DropdownMenuItem>
            ))}
          </DropdownMenuGroup>
        )}
        {sources.contextValues.length > 0 && (
          <DropdownMenuGroup>
            <DropdownMenuLabel>
              {t("action_field_group_context")}
            </DropdownMenuLabel>
            {sources.contextValues.map((entry) => (
              <DropdownMenuItem
                key={entry.ref}
                onSelect={() => onPick(entry.ref)}
              >
                {contextValueLabel(entry)}
              </DropdownMenuItem>
            ))}
          </DropdownMenuGroup>
        )}
        {(questions.length > 0 || sources.contextValues.length > 0) && (
          <DropdownMenuSeparator />
        )}
        <DropdownMenuItem onSelect={onCustomExpression}>
          {t("action_param_custom_expression")}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/** Number entry that commits only what parses — a controlled number input
 *  fed straight from the stored value would rewrite "0." to "0"
 *  mid-keystroke (see `NumericAnswerInput` in VisibilityConditionsCard). */
function NumberLiteralInput({
  id,
  value,
  onChange,
  ...rest
}: {
  id: string;
  value: unknown;
  onChange: (value: number | undefined) => void;
  "aria-label": string;
}) {
  const [buffer, setBuffer] = useState<string | null>(null);
  return (
    <Input
      id={id}
      type="number"
      value={buffer ?? (typeof value === "number" ? String(value) : "")}
      onChange={(e) => {
        setBuffer(e.target.value);
        if (e.target.value === "") onChange(undefined);
        else if (!Number.isNaN(e.target.valueAsNumber)) {
          onChange(e.target.valueAsNumber);
        }
      }}
      onBlur={() => setBuffer(null)}
      {...rest}
    />
  );
}

/** A raw `{{ … }}` expression — for whatever the token editor can't show. */
function ExpressionInput({
  id,
  expression,
  onChange,
  onClear,
  "aria-label": ariaLabel,
}: {
  id: string;
  expression: string;
  onChange: (expression: string) => void;
  onClear: () => void;
  "aria-label": string;
}) {
  const { t } = useTranslation();
  return (
    <div className="space-y-1">
      <div className="flex items-center gap-2">
        <Input
          id={id}
          aria-label={ariaLabel}
          className="font-mono text-xs"
          value={expression}
          placeholder='f"…{q_link_id}…"'
          onChange={(e) => onChange(e.target.value)}
        />
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="shrink-0"
          aria-label={t("action_param_clear_source")}
          onClick={onClear}
        >
          <X className="size-4" />
        </Button>
      </div>
      <p className="text-xs text-gray-500">{t("action_expression_help")}</p>
    </div>
  );
}

/** The message with each token shown as the thing it stands for —
 *  "Fever, temp [Temperature]". */
function MessagePreview({
  text,
  sources,
}: {
  text: string;
  sources: ActionVariableSources;
}) {
  const { t } = useTranslation();
  const parts = text.split(
    /(\{[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*\})/g,
  );
  if (parts.length < 3) return null;
  return (
    <p className="text-xs text-gray-500">
      {t("action_param_preview")}{" "}
      {parts.map((part, index) => {
        if (index % 2 === 0) return <Fragment key={index}>{part}</Fragment>;
        const ref = part.slice(1, -1);
        const question = questionOfRef(ref, sources.questions);
        const contextValue = sources.contextValues.find((v) => v.ref === ref);
        return (
          <span
            key={index}
            className="rounded bg-primary-50 px-1 font-medium text-primary-800"
          >
            {question
              ? questionLabel(question.question, t)
              : contextValue
                ? contextValueLabel(contextValue)
                : ref}
          </span>
        );
      })}
    </p>
  );
}

/**
 * One string/number instruction param.
 *
 * Strings are edited as text with `{answer}` tokens spliced in at the
 * caret — stored verbatim when there are none, as a whole-value f-string
 * template when there are (`compileMessageTemplate`). Numbers are a fixed
 * value or one whole-value reference. Anything the backend accepts that
 * these cannot show is edited as a raw expression, one click away.
 */
export function ParamValueInput({
  id,
  kind,
  value,
  onChange,
  sources,
  "aria-label": ariaLabel,
}: ParamValueInputProps) {
  const { t } = useTranslation();
  const inputRef = useRef<HTMLInputElement>(null);

  if (kind === "number") {
    const template = parseTemplate(value);
    if (template?.kind === "expression") {
      return (
        <ExpressionInput
          id={id}
          expression={template.expression}
          onChange={(expression) => onChange(`{{ ${expression} }}`)}
          onClear={() => onChange(undefined)}
          aria-label={ariaLabel}
        />
      );
    }
    if (template?.kind === "ref") {
      const question = questionOfRef(template.ref, sources.questions);
      const contextValue = sources.contextValues.find(
        (entry) => entry.ref === template.ref,
      );
      const label = question
        ? t("action_param_answer_of", {
            question: questionLabel(question.question, t),
          })
        : contextValue
          ? contextValueLabel(contextValue)
          : template.ref;
      return (
        <div className="flex items-center gap-2">
          <div
            id={id}
            className="flex h-9 min-w-0 flex-1 items-center gap-2 rounded-md border border-dashed border-primary-300 bg-primary-50 px-2.5 text-sm text-primary-900"
          >
            <Variable aria-hidden className="size-4 shrink-0" />
            <span className="truncate">{label}</span>
          </div>
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="shrink-0"
            aria-label={t("action_param_clear_source")}
            onClick={() => onChange(undefined)}
          >
            <X className="size-4" />
          </Button>
        </div>
      );
    }
    return (
      <div className="flex items-center gap-2">
        <NumberLiteralInput
          id={id}
          value={value}
          onChange={onChange}
          aria-label={ariaLabel}
        />
        <VariableSourceMenu
          sources={sources}
          onPick={(ref) => onChange(compileTemplate(ref))}
          onCustomExpression={() => onChange("{{  }}")}
        />
      </div>
    );
  }

  const parsed = parseMessageTemplate(value);
  if (parsed.kind === "expression") {
    return (
      <ExpressionInput
        id={id}
        expression={parsed.expression}
        onChange={(expression) => onChange(`{{ ${expression} }}`)}
        onClear={() => onChange("")}
        aria-label={ariaLabel}
      />
    );
  }

  const text = parsed.text;
  const insertToken = (ref: string) => {
    const element = inputRef.current;
    const start = element?.selectionStart ?? text.length;
    const end = element?.selectionEnd ?? start;
    const token = messageToken(ref);
    onChange(compileMessageTemplate(text.slice(0, start) + token + text.slice(end)));
    // The menu took focus; put the caret back after the token once the
    // controlled value has rendered.
    requestAnimationFrame(() => {
      element?.focus();
      element?.setSelectionRange(start + token.length, start + token.length);
    });
  };

  return (
    <div className="space-y-1">
      <div className="flex items-center gap-2">
        <Input
          ref={inputRef}
          id={id}
          aria-label={ariaLabel}
          value={text}
          onChange={(e) => onChange(compileMessageTemplate(e.target.value))}
        />
        <VariableSourceMenu
          sources={sources}
          onPick={insertToken}
          onCustomExpression={() =>
            onChange(text ? `{{ ${JSON.stringify(text)} }}` : "{{  }}")
          }
        />
      </div>
      <MessagePreview text={text} sources={sources} />
    </div>
  );
}

import { Trash2 } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";

import {
  ContextPathOption,
  SELF_CONTEXT_PATH,
} from "@/components/QuestionnaireV2/builder/actionVariables";

import {
  ActionInstructionDefinition,
  ActionParamSchema,
  QuestionnaireActionInstruction,
} from "@/types/questionnaire/actions";

import { ParamValueInput } from "./ParamValueInput";
import {
  ActionVariableSources,
  contextPathLabel,
  humanize,
  instructionLabel,
  instructionTypeLabel,
} from "./labels";

type ParamKind = "string" | "number" | "boolean" | "enum" | "json";

/** Pydantic renders `str | None` as `anyOf` — the first non-null branch is
 *  the one the author fills in. */
function resolveSchema(schema: ActionParamSchema): ActionParamSchema {
  if (!schema.anyOf) return schema;
  return (
    schema.anyOf.find((branch) => branch.type !== "null") ?? schema.anyOf[0]
  );
}

function paramKindOf(schema: ActionParamSchema): ParamKind {
  const resolved = resolveSchema(schema);
  const type = Array.isArray(resolved.type)
    ? resolved.type.find((entry) => entry !== "null")
    : resolved.type;
  if (resolved.enum && resolved.enum.every((v) => typeof v === "string")) {
    return "enum";
  }
  switch (type) {
    case "string":
      return "string";
    case "integer":
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    default:
      return "json";
  }
}

/** The params a freshly picked instruction starts with — schema defaults
 *  only, so a required param without one stays blank and the save rule
 *  flags it. */
export function defaultParams(
  definition: ActionInstructionDefinition,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(definition.input_schema.properties ?? {})
      .filter(([, schema]) => schema.default !== undefined)
      .map(([name, schema]) => [name, schema.default]),
  );
}

/**
 * The context path an instruction is applied to: the one reachable path
 * whose type matches its declared context, else the submission itself.
 * Not an author choice — nothing on the backend distinguishes the two
 * today, so there is no control for it, only a line saying what resolved.
 */
export function defaultContextPath(
  definition: ActionInstructionDefinition | undefined,
  contextPaths: ContextPathOption[],
): string {
  const matches = definition
    ? contextPaths.filter((option) => option.contextType === definition.context)
    : [];
  return matches.length === 1 ? matches[0].path : SELF_CONTEXT_PATH;
}

/** A fresh instruction for `definition`, params at their defaults. */
export function newInstruction(
  definition: ActionInstructionDefinition,
  contextPaths: ContextPathOption[],
): QuestionnaireActionInstruction {
  return {
    slug: definition.slug,
    params: defaultParams(definition),
    context: defaultContextPath(definition, contextPaths),
  };
}

/** Anything the typed controls cannot express is edited as JSON text —
 *  committed on blur, and kept as text while it does not parse. */
function JsonParamInput({
  id,
  value,
  onChange,
  "aria-label": ariaLabel,
}: {
  id: string;
  value: unknown;
  onChange: (value: unknown) => void;
  "aria-label": string;
}) {
  const { t } = useTranslation();
  const [text, setText] = useState(() =>
    value === undefined ? "" : JSON.stringify(value, null, 2),
  );
  const [invalid, setInvalid] = useState(false);
  return (
    <div className="space-y-1">
      <Textarea
        id={id}
        aria-label={ariaLabel}
        aria-invalid={invalid}
        className="font-mono text-xs"
        rows={3}
        value={text}
        onChange={(e) => setText(e.target.value)}
        onBlur={() => {
          if (text.trim() === "") {
            setInvalid(false);
            onChange(undefined);
            return;
          }
          try {
            onChange(JSON.parse(text));
            setInvalid(false);
          } catch {
            setInvalid(true);
          }
        }}
      />
      {invalid && (
        <p className="text-xs text-red-600">{t("action_param_json_invalid")}</p>
      )}
    </div>
  );
}

interface InstructionEditorProps {
  /** Stable per-instruction DOM id prefix. */
  idPrefix: string;
  instruction: QuestionnaireActionInstruction;
  definitions: ActionInstructionDefinition[] | undefined;
  contextPaths: ContextPathOption[];
  sources: ActionVariableSources;
  onChange: (instruction: QuestionnaireActionInstruction) => void;
  onRemove: () => void;
}

/**
 * One "Then" step: which registered instruction runs and the inputs its
 * `input_schema` declares. Instruction and type names are plain language
 * (`labels.ts`); the registry slug never reaches the screen.
 */
export function InstructionEditor({
  idPrefix,
  instruction,
  definitions,
  contextPaths,
  sources,
  onChange,
  onRemove,
}: InstructionEditorProps) {
  const { t } = useTranslation();
  const definition = definitions?.find(
    (candidate) => candidate.slug === instruction.slug,
  );
  // A saved slug the registry no longer serves — kept visible (and
  // flagged) rather than blanked, so the author sees what was there.
  const unknownSlug =
    !!definitions && !!instruction.slug && !definition
      ? instruction.slug
      : undefined;
  const properties = Object.entries(definition?.input_schema.properties ?? {});
  const required = new Set(definition?.input_schema.required ?? []);
  const runsOn = contextPaths.find(
    (option) => option.path === instruction.context,
  );

  const setParam = (name: string, value: unknown) => {
    const params = { ...instruction.params };
    if (value === undefined) delete params[name];
    else params[name] = value;
    onChange({ ...instruction, params });
  };

  return (
    <div className="space-y-3 rounded-md bg-gray-50 p-3">
      <div className="flex items-center justify-between gap-2">
        <span className="text-sm font-medium text-gray-900">
          {t("action_instruction")}
        </span>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="size-6"
          onClick={onRemove}
          aria-label={t("action_remove_instruction")}
        >
          <Trash2 className="size-4" />
        </Button>
      </div>

      <Select
        value={instruction.slug || undefined}
        onValueChange={(slug) => {
          const next = definitions?.find(
            (candidate) => candidate.slug === slug,
          );
          onChange(
            next
              ? newInstruction(next, contextPaths)
              : { slug, params: {}, context: SELF_CONTEXT_PATH },
          );
        }}
      >
        <SelectTrigger
          className="w-full"
          aria-label={t("action_instruction")}
          aria-invalid={Boolean(unknownSlug)}
        >
          <SelectValue placeholder={t("action_instruction_placeholder")} />
        </SelectTrigger>
        <SelectContent>
          {unknownSlug && (
            <SelectItem value={unknownSlug} disabled className="text-red-600">
              {humanize(unknownSlug)}
            </SelectItem>
          )}
          {(definitions ?? []).map((candidate) => (
            <SelectItem key={candidate.slug} value={candidate.slug}>
              <span className="flex items-center gap-2">
                {instructionLabel(candidate.slug, t)}
                <Badge variant="secondary" className="text-[10px]">
                  {instructionTypeLabel(candidate.instruction_type, t)}
                </Badge>
              </span>
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      {unknownSlug && (
        <p className="text-xs text-red-600">
          {t("action_instruction_unknown")}
        </p>
      )}

      {properties.map(([name, schema]) => {
        const kind = paramKindOf(schema);
        const resolved = resolveSchema(schema);
        const id = `${idPrefix}-param-${name}`;
        const label = schema.title ?? humanize(name);
        const value = instruction.params[name];
        return (
          <div key={name} className="space-y-1.5">
            <Label htmlFor={id} className="text-xs font-medium text-gray-600">
              {label}
              {required.has(name) ? (
                <span className="text-red-600"> *</span>
              ) : (
                <span className="font-normal text-gray-400">
                  {" "}
                  · {t("optional")}
                </span>
              )}
            </Label>
            {schema.description && (
              <p className="text-xs text-gray-500">{schema.description}</p>
            )}
            {kind === "boolean" ? (
              <Switch
                id={id}
                aria-label={label}
                checked={value === true}
                onCheckedChange={(checked) => setParam(name, checked)}
              />
            ) : kind === "enum" ? (
              <Select
                value={typeof value === "string" ? value : undefined}
                onValueChange={(next) => setParam(name, next)}
              >
                <SelectTrigger id={id} className="w-full" aria-label={label}>
                  <SelectValue placeholder={t("select")} />
                </SelectTrigger>
                <SelectContent>
                  {(resolved.enum ?? []).map((option) => (
                    <SelectItem key={String(option)} value={String(option)}>
                      {String(option)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            ) : kind === "json" ? (
              <JsonParamInput
                id={id}
                value={value}
                onChange={(next) => setParam(name, next)}
                aria-label={label}
              />
            ) : (
              <ParamValueInput
                id={id}
                kind={kind}
                value={value}
                onChange={(next) => setParam(name, next)}
                sources={sources}
                aria-label={label}
              />
            )}
          </div>
        );
      })}

      {/* Said only when it is not the submission itself — the default needs
          no explaining, a neighbour ("Patient") does. */}
      {instruction.context && instruction.context !== SELF_CONTEXT_PATH && (
        <p className="text-xs text-gray-500">
          {t("action_runs_on", {
            context: runsOn
              ? contextPathLabel(runsOn, t)
              : instruction.context,
          })}
        </p>
      )}
    </div>
  );
}

import { Plus, TriangleAlert, Trash2 } from "lucide-react";
import { useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";

import { ChoiceChip } from "@/components/QuestionnaireV2/shared/ChoiceChip";
import {
  ActionRule,
  ActionRuleBehavior,
  ActionRuleValue,
  compileCondition,
  parseCondition,
  questionRef,
  referenceableLinkId,
} from "@/components/QuestionnaireV2/shared/actionExpression";

import {
  AnswerShape,
  QuestionVariable,
  operatorsFor,
  questionOfRef,
} from "@/components/QuestionnaireV2/builder/actionVariables";

import { Question } from "@/types/questionnaire/question";

import {
  ActionVariableSources,
  contextValueLabel,
  numberedQuestionLabel,
  operatorLabel,
  questionLabel,
} from "./labels";

interface ActionConditionEditorProps {
  /** Stable DOM id prefix for this action's controls. */
  idPrefix: string;
  condition: string;
  onChange: (condition: string) => void;
  sources: ActionVariableSources;
  /** A legacy `Q-…` link id was picked: rename it so it can be named from
   *  an expression (the reducer follows the rename through enable_when and
   *  every action). */
  onRenameLinkId: (questionId: string, linkId: string) => void;
  onMarkRequired: (questionId: string) => void;
}

const NUMERIC_TEXT = /^-?\d+(\.\d+)?$/;

/** The value a fresh rule starts with, so every row compiles from the
 *  moment it exists — a half-built row would have no valid expression to
 *  persist. */
function defaultValue(
  shape: AnswerShape | undefined,
  question: Question | undefined,
): ActionRuleValue {
  switch (shape) {
    case "boolean":
      return true;
    case "number":
      return 0;
    case "choice":
    case "choice_multi":
      return question?.answer_option?.[0]?.value ?? "";
    default:
      return "";
  }
}

/** Number entry that commits only what parses (see `NumericAnswerInput`
 *  in VisibilityConditionsCard for why a bare controlled input won't do). */
function NumericRuleValue({
  value,
  onChange,
  "aria-label": ariaLabel,
}: {
  value: ActionRuleValue;
  onChange: (next: number) => void;
  "aria-label": string;
}) {
  const [buffer, setBuffer] = useState<string | null>(null);
  return (
    <Input
      type="number"
      aria-label={ariaLabel}
      value={buffer ?? String(value ?? "")}
      onChange={(e) => {
        setBuffer(e.target.value);
        if (e.target.value !== "" && !Number.isNaN(e.target.valueAsNumber)) {
          onChange(e.target.valueAsNumber);
        }
      }}
      onBlur={() => setBuffer(null)}
    />
  );
}

/** Whether a question, or any group above it, is shown conditionally —
 *  then it can be absent from a submission however required it is. */
function isConditional(question: Question, all: Question[]): boolean {
  const path = (list: Question[], trail: Question[]): Question[] | null => {
    for (const candidate of list) {
      const next = [...trail, candidate];
      if (candidate.id === question.id) return next;
      const found = path(candidate.questions ?? [], next);
      if (found) return found;
    }
    return null;
  };
  return (path(all, []) ?? []).some(
    (ancestor) => (ancestor.enable_when?.length ?? 0) > 0,
  );
}

/**
 * The "When" half of an action. Two faces over one stored string: the rule
 * builder (field / operator / value rows joined by AND or OR) for the
 * canonical subset `actionExpression` round-trips, and a plain expression
 * editor for everything else. Mirrors the Logic tab's grammar: no rules
 * means "runs on every submission", the first "Add a condition" makes it
 * conditional, deleting the last rule takes it back.
 */
export function ActionConditionEditor({
  idPrefix,
  condition,
  onChange,
  sources,
  onRenameLinkId,
  onMarkRequired,
}: ActionConditionEditorProps) {
  const { t } = useTranslation();
  const { questions, contextValues } = sources;
  const parsed = parseCondition(condition);
  const [wantsExpression, setWantsExpression] = useState(false);
  const [confirmReplace, setConfirmReplace] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const expressionMode = wantsExpression || !parsed;

  // Everything in the tree, for the rename's collision check.
  const takenLinkIds = new Set(
    questions.map((entry) => entry.question.link_id),
  );
  const pickable = questions.filter(
    (entry) => !entry.unusable || entry.unusable === "link_id",
  );
  const canAddRule = pickable.length > 0 || contextValues.length > 0;

  const update = (rules: ActionRule[], behavior: ActionRuleBehavior) =>
    onChange(compileCondition(rules, behavior));

  /** The ref a picked question should be stored under — renaming a
   *  legacy link id on the way, since `q_Q-1234` is not a name. */
  const resolveRef = (entry: QuestionVariable): string => {
    if (entry.unusable !== "link_id") return entry.ref;
    const linkId = referenceableLinkId(entry.question.link_id, takenLinkIds);
    onRenameLinkId(entry.question.id, linkId);
    return entry.ref.replace(
      questionRef(entry.question.link_id),
      questionRef(linkId),
    );
  };

  const freshRule = (entry: QuestionVariable | undefined, ref: string) => ({
    ref,
    operator: operatorsFor(entry?.shape)[0],
    value: defaultValue(entry?.shape, entry?.question),
  });

  const addRule = () => {
    if (!parsed) return;
    const first = pickable.find((entry) => !entry.unusable) ?? pickable[0];
    const ref = first ? resolveRef(first) : contextValues[0]?.ref;
    if (!ref) return;
    update([...parsed.rules, freshRule(first, ref)], parsed.behavior);
  };

  const setRule = (index: number, rule: ActionRule) => {
    if (!parsed) return;
    const rules = [...parsed.rules];
    rules[index] = rule;
    update(rules, parsed.behavior);
  };

  const insertAtCaret = (text: string) => {
    const element = textareaRef.current;
    const start = element?.selectionStart ?? condition.length;
    const end = element?.selectionEnd ?? start;
    onChange(condition.slice(0, start) + text + condition.slice(end));
    requestAnimationFrame(() => {
      element?.focus();
      element?.setSelectionRange(start + text.length, start + text.length);
    });
  };

  if (expressionMode) {
    const chips = [
      ...pickable
        .filter((entry) => !entry.unusable)
        .map((entry) => ({
          key: entry.question.id,
          label: questionLabel(entry.question, t),
          insert: compileCondition(
            [{ ref: entry.ref, operator: "==", value: "" }],
            "all",
          ).split(" == ")[0],
        })),
      ...contextValues.map((entry) => ({
        key: entry.ref,
        label: contextValueLabel(entry),
        insert: compileCondition(
          [{ ref: entry.ref, operator: "==", value: "" }],
          "all",
        ).split(" == ")[0],
      })),
    ];
    return (
      <div className="space-y-2">
        <Textarea
          ref={textareaRef}
          id={`${idPrefix}-expression`}
          aria-label={t("action_expression")}
          className="font-mono text-xs"
          rows={3}
          value={condition}
          onChange={(e) => onChange(e.target.value)}
        />
        {chips.length > 0 && (
          <div className="flex flex-wrap gap-1">
            {chips.map((chip) => (
              <button
                key={chip.key}
                type="button"
                onClick={() => insertAtCaret(chip.insert)}
                className="rounded-md border border-gray-200 bg-white px-2 py-0.5 text-xs text-gray-700 hover:border-primary-300 hover:text-primary-800"
              >
                {chip.label}
              </button>
            ))}
          </div>
        )}
        <p className="text-xs text-gray-500">{t("action_expression_help")}</p>
        {!parsed && !wantsExpression && (
          <p className="text-xs text-gray-500">
            {t("action_custom_expression_note")}
          </p>
        )}
        {confirmReplace ? (
          <div className="space-y-2 rounded-md border border-amber-200 bg-amber-50 p-3 text-xs text-amber-900">
            <p>{t("action_replace_expression_confirm")}</p>
            <div className="flex gap-2">
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={() => {
                  setConfirmReplace(false);
                  setWantsExpression(false);
                  update([], "all");
                }}
              >
                {t("action_replace_expression")}
              </Button>
              <Button
                type="button"
                size="sm"
                variant="ghost"
                onClick={() => setConfirmReplace(false)}
              >
                {t("action_keep_expression")}
              </Button>
            </div>
          </div>
        ) : (
          <Button
            type="button"
            variant="link"
            size="sm"
            className="h-auto px-0"
            onClick={() => {
              if (parsed) setWantsExpression(false);
              else setConfirmReplace(true);
            }}
          >
            {t("action_back_to_conditions")}
          </Button>
        )}
      </div>
    );
  }

  const { rules, behavior } = parsed;
  const referenced = rules
    .map((rule) => questionOfRef(rule.ref, questions)?.question)
    .filter((question): question is Question => !!question);
  const allQuestions = questions.map((entry) => entry.question);
  // Answering is what puts `q_<link_id>` into the evaluator's namespace: a
  // referenced question left blank makes the backend raise and the whole
  // submission fail. Optional ones get a warning and a one-click fix;
  // conditionally shown ones cannot be fixed that way — the save rule
  // blocks those, this just says why.
  const conditional = referenced.filter((question) =>
    isConditional(question, allQuestions),
  );
  const optional = referenced.filter(
    (question) => !question.required && !conditional.includes(question),
  );

  return (
    <div className="space-y-3">
      {rules.length === 0 && (
        <div className="rounded-lg border border-dashed border-gray-300 p-5 text-center">
          <p className="text-sm font-medium text-gray-900">
            {t("action_always_runs")}
          </p>
          <p className="text-xs text-gray-500">{t("action_always_runs_hint")}</p>
        </div>
      )}

      {rules.length > 0 && (
        <div className="space-y-1.5">
          <p className="text-xs font-medium text-gray-500">
            {t("action_run_when")}
          </p>
          <div className="flex flex-wrap gap-2">
            <ChoiceChip
              control="radio"
              label={t("all_conditions_and")}
              checked={behavior === "all"}
              onCheckedChange={() => update(rules, "all")}
            />
            <ChoiceChip
              control="radio"
              label={t("any_condition_or")}
              checked={behavior === "any"}
              onCheckedChange={() => update(rules, "any")}
            />
          </div>
        </div>
      )}

      <div className="space-y-2">
        {rules.map((rule, index) => {
          const target = questionOfRef(rule.ref, questions);
          const shape = target?.shape;
          const operators = operatorsFor(shape);
          const options = target?.question.answer_option ?? [];
          const rowLabel = t("condition_n", { n: index + 1 });
          const unresolved =
            !target && !contextValues.some((v) => v.ref === rule.ref);
          return (
            <div key={index}>
              {index > 0 && (
                <div className="relative flex justify-start py-1 pl-6">
                  <span
                    className="absolute left-[1.375rem] top-0 h-full w-px bg-gray-200"
                    aria-hidden
                  />
                  <span className="relative rounded-md border border-gray-200 bg-white px-2 py-0.5 text-xs font-semibold uppercase text-gray-500">
                    {behavior === "all" ? t("and") : t("or")}
                  </span>
                </div>
              )}
              <div className="space-y-2 rounded-md bg-gray-50 p-3">
                <div className="flex items-center justify-between">
                  <span className="text-sm font-medium text-gray-900">
                    {rowLabel}
                  </span>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="size-6"
                    onClick={() =>
                      update(
                        rules.filter((_, i) => i !== index),
                        behavior,
                      )
                    }
                    aria-label={t("delete")}
                  >
                    <Trash2 className="size-4" />
                  </Button>
                </div>

                <div className="grid gap-2 sm:grid-cols-2">
                  <div className="space-y-1 sm:col-span-2">
                    <p className="text-xs text-gray-500">{t("action_field")}</p>
                    <Select
                      value={rule.ref}
                      onValueChange={(picked) => {
                        const entry = questions.find(
                          (candidate) => candidate.ref === picked,
                        );
                        setRule(
                          index,
                          freshRule(entry, entry ? resolveRef(entry) : picked),
                        );
                      }}
                    >
                      <SelectTrigger
                        className="w-full"
                        aria-label={`${rowLabel} ${t("action_field")}`}
                        aria-invalid={unresolved}
                      >
                        <SelectValue placeholder={t("select")} />
                      </SelectTrigger>
                      <SelectContent>
                        {/* A ref that names nothing current (deleted
                            question, registry change) stays visible so the
                            author can see what to fix. */}
                        {unresolved && (
                          <SelectItem
                            value={rule.ref}
                            disabled
                            className="text-red-600"
                          >
                            {rule.ref}
                          </SelectItem>
                        )}
                        {questions.length > 0 && (
                          <SelectGroup>
                            <SelectLabel>
                              {t("action_field_group_answers")}
                            </SelectLabel>
                            {questions.map((entry) => (
                              <SelectItem
                                key={entry.question.id}
                                value={entry.ref}
                                disabled={
                                  !!entry.unusable &&
                                  entry.unusable !== "link_id"
                                }
                              >
                                {numberedQuestionLabel(
                                  entry.question,
                                  sources.numbers,
                                  t,
                                )}
                                {entry.unusable &&
                                  entry.unusable !== "link_id" && (
                                    <span className="ml-1 text-xs text-gray-400">
                                      · {t(`action_unusable_${entry.unusable}`)}
                                    </span>
                                  )}
                              </SelectItem>
                            ))}
                          </SelectGroup>
                        )}
                        {contextValues.length > 0 && (
                          <SelectGroup>
                            <SelectLabel>
                              {t("action_field_group_context")}
                            </SelectLabel>
                            {contextValues.map((entry) => (
                              <SelectItem key={entry.ref} value={entry.ref}>
                                {contextValueLabel(entry)}
                              </SelectItem>
                            ))}
                          </SelectGroup>
                        )}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-1">
                    <p className="text-xs text-gray-500">{t("operator")}</p>
                    <Select
                      value={rule.operator}
                      onValueChange={(value) => {
                        const operator = operators.find((o) => o === value);
                        if (operator) setRule(index, { ...rule, operator });
                      }}
                    >
                      <SelectTrigger
                        className="w-full"
                        aria-label={`${rowLabel} ${t("operator")}`}
                      >
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {operators.map((operator) => (
                          <SelectItem key={operator} value={operator}>
                            {operatorLabel(operator, t)}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-1">
                    <p className="text-xs text-gray-500">{t("action_value")}</p>
                    {shape === "boolean" ? (
                      <Select
                        value={rule.value === true ? "true" : "false"}
                        onValueChange={(value) =>
                          setRule(index, { ...rule, value: value === "true" })
                        }
                      >
                        <SelectTrigger
                          className="w-full"
                          aria-label={`${rowLabel} ${t("action_value")}`}
                        >
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="true">{t("yes")}</SelectItem>
                          <SelectItem value="false">{t("no")}</SelectItem>
                        </SelectContent>
                      </Select>
                    ) : shape === "number" ? (
                      <NumericRuleValue
                        value={rule.value}
                        onChange={(value) => setRule(index, { ...rule, value })}
                        aria-label={`${rowLabel} ${t("action_value")}`}
                      />
                    ) : (shape === "choice" || shape === "choice_multi") &&
                      options.length > 0 ? (
                      <Select
                        value={String(rule.value)}
                        onValueChange={(value) =>
                          setRule(index, { ...rule, value })
                        }
                      >
                        <SelectTrigger
                          className="w-full"
                          aria-label={`${rowLabel} ${t("action_value")}`}
                        >
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {options.map((option) => (
                            <SelectItem key={option.value} value={option.value}>
                              {option.display || option.value}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    ) : (
                      <Input
                        aria-label={`${rowLabel} ${t("action_value")}`}
                        value={String(rule.value ?? "")}
                        onChange={(e) => {
                          const text = e.target.value;
                          // Context values carry no type: a numeric entry
                          // compares as a number, anything else as text.
                          const value =
                            !shape && NUMERIC_TEXT.test(text)
                              ? Number(text)
                              : text;
                          setRule(index, { ...rule, value });
                        }}
                      />
                    )}
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {conditional.length > 0 && (
        <p className="flex items-start gap-2 rounded-md border border-red-200 bg-red-50 p-2.5 text-xs text-red-900">
          <TriangleAlert aria-hidden className="mt-0.5 size-3.5 shrink-0" />
          {t("action_rule_conditional_question", {
            question: conditional.map((q) => questionLabel(q, t)).join(", "),
          })}
        </p>
      )}
      {optional.length > 0 && (
        <div className="space-y-1.5 rounded-md border border-amber-200 bg-amber-50 p-2.5 text-xs text-amber-900">
          <p className="flex items-start gap-2">
            <TriangleAlert aria-hidden className="mt-0.5 size-3.5 shrink-0" />
            {t("action_rule_unanswered_hazard", {
              question: optional.map((q) => questionLabel(q, t)).join(", "),
            })}
          </p>
          <div className="flex flex-wrap gap-2 pl-5">
            {optional.map((question) => (
              <Button
                key={question.id}
                type="button"
                variant="link"
                size="sm"
                className="h-auto px-0 text-amber-900 underline"
                onClick={() => onMarkRequired(question.id)}
              >
                {t("action_mark_required", {
                  question: questionLabel(question, t),
                })}
              </Button>
            ))}
          </div>
        </div>
      )}

      <div className="flex flex-wrap items-center gap-3">
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={addRule}
          disabled={!canAddRule}
        >
          <Plus className="size-4" />
          {t("add_a_condition")}
        </Button>
        <Button
          type="button"
          variant="link"
          size="sm"
          className="h-auto px-0"
          onClick={() => setWantsExpression(true)}
        >
          {t("action_edit_as_expression")}
        </Button>
      </div>
      {!canAddRule && (
        <p className="text-xs text-gray-500">
          {t("action_no_fields_available")}
        </p>
      )}
    </div>
  );
}

/**
 * Save-time rules for questionnaire actions — the counterpart of
 * `saveValidation.ts` for the question tree. Each rule names the first
 * action it fails on; the studio blocks Save until the list is empty.
 *
 * The backend only rejects an unknown instruction slug and missing
 * `condition`/`context` fields at save time; a bad expression, a missing
 * required param or a reference to a deleted or conditionally-shown
 * question would otherwise sail through the PUT and break every
 * SUBMISSION of the questionnaire instead.
 */
import {
  ActionInstructionDefinition,
  QuestionnaireAction,
} from "@/types/questionnaire/actions";
import { Question } from "@/types/questionnaire/question";

import {
  actionReferencedLinkIds,
  lintExpression,
  parseTemplate,
} from "@/components/QuestionnaireV2/shared/actionExpression";

export interface ActionIssue {
  /** Index into the questionnaire's `actions` array. */
  index: number;
  messageKey: string;
}

export interface ActionCheckContext {
  questions: Question[];
  /** Undefined until the registry has loaded — the slug rules stand down
   *  rather than flag every action as unknown while the request is in
   *  flight. */
  instructions?: ActionInstructionDefinition[];
}

interface TreeIndex {
  linkIds: Set<string>;
  /** link_ids of questions that are shown conditionally — themselves or
   *  through an enclosing group — and so can be absent from a submission
   *  however required they are. */
  conditional: Set<string>;
}

function indexTree(questions: Question[]): TreeIndex {
  const index: TreeIndex = { linkIds: new Set(), conditional: new Set() };
  const walk = (list: Question[], underCondition: boolean) => {
    for (const question of list) {
      const conditional =
        underCondition || (question.enable_when?.length ?? 0) > 0;
      index.linkIds.add(question.link_id);
      if (conditional) index.conditional.add(question.link_id);
      walk(question.questions ?? [], conditional);
    }
  };
  walk(questions, false);
  return index;
}

function isBlank(value: unknown): boolean {
  if (value === undefined || value === null) return true;
  if (typeof value !== "string") return false;
  if (value.trim() === "") return true;
  const template = parseTemplate(value);
  return template?.kind === "expression" && template.expression === "";
}

/** Every expression an action evaluates: its condition and each templated
 *  param's inner expression. */
function expressionsOf(action: QuestionnaireAction): string[] {
  const expressions = [action.condition];
  for (const instruction of action.instructions) {
    for (const value of Object.values(instruction.params)) {
      const template = parseTemplate(value);
      if (template) {
        expressions.push(
          template.kind === "ref" ? template.ref : template.expression,
        );
      }
    }
  }
  return expressions;
}

interface ActionRule {
  predicate: (
    action: QuestionnaireAction,
    tree: TreeIndex,
    instructions: ActionInstructionDefinition[] | undefined,
  ) => boolean;
  messageKey: string;
}

const ACTION_RULES: ActionRule[] = [
  {
    predicate: (action) => action.condition.trim() === "",
    messageKey: "action_issue_condition_empty",
  },
  {
    predicate: (action) =>
      expressionsOf(action).some(
        (expression) => lintExpression(expression) === "attribute",
      ),
    messageKey: "action_issue_expression_attribute",
  },
  {
    predicate: (action) =>
      expressionsOf(action).some(
        (expression) =>
          expression.trim() !== "" && lintExpression(expression) === "syntax",
      ),
    messageKey: "action_issue_expression_syntax",
  },
  {
    predicate: (action) => action.instructions.length === 0,
    messageKey: "action_issue_no_instructions",
  },
  {
    predicate: (action) =>
      action.instructions.some((instruction) => !instruction.slug),
    messageKey: "action_issue_instruction_missing",
  },
  {
    predicate: (action, _tree, instructions) =>
      !!instructions &&
      action.instructions.some(
        (instruction) =>
          instruction.slug &&
          !instructions.some(
            (definition) => definition.slug === instruction.slug,
          ),
      ),
    messageKey: "action_issue_instruction_unknown",
  },
  {
    predicate: (action) =>
      action.instructions.some((instruction) => !instruction.context),
    messageKey: "action_issue_context_missing",
  },
  {
    predicate: (action, _tree, instructions) =>
      !!instructions &&
      action.instructions.some((instruction) => {
        const definition = instructions.find(
          (candidate) => candidate.slug === instruction.slug,
        );
        return (definition?.input_schema.required ?? []).some((name) =>
          isBlank(instruction.params[name]),
        );
      }),
    messageKey: "action_issue_param_required",
  },
  {
    predicate: (action, { linkIds }) =>
      actionReferencedLinkIds(action).some((linkId) => !linkIds.has(linkId)),
    messageKey: "action_issue_unknown_question",
  },
  {
    predicate: (action, { conditional }) =>
      actionReferencedLinkIds(action).some((linkId) =>
        conditional.has(linkId),
      ),
    messageKey: "action_issue_conditional_question",
  },
];

/** The first failing rule per action, in action order. */
export function findActionIssues(
  actions: QuestionnaireAction[],
  { questions, instructions }: ActionCheckContext,
): ActionIssue[] {
  const tree = indexTree(questions);
  const issues: ActionIssue[] = [];
  actions.forEach((action, index) => {
    const failing = ACTION_RULES.find((rule) =>
      rule.predicate(action, tree, instructions),
    );
    if (failing) issues.push({ index, messageKey: failing.messageKey });
  });
  return issues;
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import type {
  ActionInstructionDefinition,
  QuestionnaireAction,
} from "@/types/questionnaire/actions";
import type { Question } from "@/types/questionnaire/question";

import { findActionIssues } from "./actionValidation";

const questions: Question[] = [
  { id: "1", link_id: "fever", text: "Fever", type: "boolean" },
  {
    id: "2",
    link_id: "vitals",
    text: "Vitals",
    type: "group",
    questions: [{ id: "3", link_id: "temp", text: "Temp", type: "decimal" }],
  },
  {
    id: "4",
    link_id: "followup",
    text: "Follow up",
    type: "string",
    enable_when: [{ question: "fever", operator: "equals", answer: "Yes" }],
  },
  {
    id: "5",
    link_id: "hidden_group",
    text: "Hidden group",
    type: "group",
    enable_when: [{ question: "fever", operator: "equals", answer: "Yes" }],
    questions: [{ id: "6", link_id: "inner", text: "Inner", type: "string" }],
  },
];

const logging: ActionInstructionDefinition = {
  slug: "logging",
  input_schema: {
    properties: { message: { type: "string" } },
    required: ["message"],
  },
  output_schema: {},
  context: "Appointment",
  instruction_type: "NOTIFY",
};

const valid: QuestionnaireAction = {
  condition: "q_fever == True and q_temp > 38",
  instructions: [
    {
      slug: "logging",
      params: { message: '{{ f"temp {q_temp}" }}' },
      context: "self",
    },
  ],
};

const context = { questions, instructions: [logging] };

describe("findActionIssues", () => {
  it("passes a well-formed action", () => {
    assert.deepEqual(findActionIssues([valid], context), []);
  });

  it("reports the first failing rule per action, in action order", () => {
    const withInstruction = (params: Record<string, unknown>, ctx = "self") => ({
      ...valid,
      instructions: [{ slug: "logging", params, context: ctx }],
    });
    const issues = findActionIssues(
      [
        { ...valid, condition: "  " },
        { ...valid, condition: "patient.age > 1" },
        { ...valid, condition: 'q_fever == "x' },
        withInstruction({ message: '{{ f"{q_temp" }}' }),
        { ...valid, instructions: [] },
        { ...valid, instructions: [{ slug: "", params: {}, context: "self" }] },
        { ...valid, instructions: [{ slug: "nope", params: {}, context: "self" }] },
        withInstruction({ message: "x" }, ""),
        withInstruction({ message: " " }),
        withInstruction({ message: "{{  }}" }),
        { ...valid, condition: "q_gone == True" },
        withInstruction({ message: "{{ q_gone }}" }),
        { ...valid, condition: 'q_followup == "x"' },
        withInstruction({ message: "{{ q_inner }}" }),
      ],
      context,
    );
    assert.deepEqual(issues, [
      { index: 0, messageKey: "action_issue_condition_empty" },
      { index: 1, messageKey: "action_issue_expression_attribute" },
      { index: 2, messageKey: "action_issue_expression_syntax" },
      { index: 3, messageKey: "action_issue_expression_syntax" },
      { index: 4, messageKey: "action_issue_no_instructions" },
      { index: 5, messageKey: "action_issue_instruction_missing" },
      { index: 6, messageKey: "action_issue_instruction_unknown" },
      { index: 7, messageKey: "action_issue_context_missing" },
      { index: 8, messageKey: "action_issue_param_required" },
      { index: 9, messageKey: "action_issue_param_required" },
      { index: 10, messageKey: "action_issue_unknown_question" },
      { index: 11, messageKey: "action_issue_unknown_question" },
      { index: 12, messageKey: "action_issue_conditional_question" },
      { index: 13, messageKey: "action_issue_conditional_question" },
    ]);
  });

  it("stands down the registry rules until the registry has loaded", () => {
    const issues = findActionIssues(
      [
        {
          ...valid,
          instructions: [{ slug: "nope", params: {}, context: "self" }],
        },
      ],
      { questions },
    );
    assert.deepEqual(issues, []);
  });
});

import type { TFunction } from "i18next";

import { parseCondition } from "@/components/QuestionnaireV2/shared/actionExpression";

import {
  ContextValueVariable,
  QuestionVariable,
  questionOfRef,
} from "@/components/QuestionnaireV2/builder/actionVariables";
import {
  contextValueLabel,
  instructionLabel,
  operatorLabel,
  questionLabel,
} from "@/components/QuestionnaireV2/builder/actions/labels";

import type { QuestionnaireAction } from "@/types/questionnaire/actions";

/**
 * The one line an author scans per action card — the counterpart of
 * `conditionSummary.ts` for visibility rules. Reads the condition through
 * the same parser the editor uses; a custom expression is quoted verbatim.
 */
export function actionPlainWords(
  action: QuestionnaireAction,
  questions: QuestionVariable[],
  contextValues: ContextValueVariable[],
  t: TFunction,
): string {
  const parsed = parseCondition(action.condition);
  let when: string;
  if (!parsed) {
    when = t("action_plain_when_expression", {
      expression: action.condition.trim(),
    });
  } else if (parsed.rules.length === 0) {
    when = t("action_plain_every_submission");
  } else {
    const joiner =
      parsed.behavior === "any"
        ? ` ${t("or").toLowerCase()} `
        : ` ${t("and").toLowerCase()} `;
    const clauses = parsed.rules.map((rule) => {
      const target = questionOfRef(rule.ref, questions);
      const contextValue = contextValues.find((v) => v.ref === rule.ref);
      const field = target
        ? questionLabel(target.question, t)
        : contextValue
          ? contextValueLabel(contextValue)
          : rule.ref;
      const value =
        typeof rule.value === "boolean"
          ? t(rule.value ? "yes" : "no")
          : String(rule.value);
      return t("action_plain_rule", {
        field,
        operator: operatorLabel(rule.operator, t).toLowerCase(),
        value,
      });
    });
    when = t("action_plain_when", { rules: clauses.join(joiner) });
  }
  const then =
    action.instructions.length === 0
      ? t("action_plain_nothing")
      : action.instructions
          .map((instruction) =>
            instruction.slug ? instructionLabel(instruction.slug, t) : "?",
          )
          .join(", ");
  return t("action_plain_sentence", { when, then });
}

import type { ActionOutcome } from "@/types/questionnaire/actions";

/**
 * What the backend's questionnaire actions reported back on a successful
 * submission — the `_actions` list the submit view appends to its response
 * (`QuestionnaireViewSet.submit`), one entry per instruction that ran, and
 * carried through the batch endpoint as `results[i].data._actions`.
 *
 * Only the `{message}` convention the shipped instructions follow is read;
 * an outcome with no readable message is not shown. Other outcome shapes
 * (redirects, validation verdicts) get handled when an instruction that
 * produces them exists.
 */

interface BatchResultLike {
  reference_id?: string;
  data?: unknown;
}

function isOutcome(value: unknown): value is ActionOutcome {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as ActionOutcome).slug === "string" &&
    typeof (value as ActionOutcome).instruction_type === "string"
  );
}

/**
 * The outcomes from every questionnaire-submit result in a batch response.
 * `submitReferenceIds` are the reference ids `composeBatch` gave those
 * requests (the questionnaire ids) — structured-type requests to domain
 * APIs and the draft-completion PUT never carry `_actions`.
 */
export function collectActionOutcomes(
  results: BatchResultLike[],
  submitReferenceIds: ReadonlySet<string>,
): ActionOutcome[] {
  const outcomes: ActionOutcome[] = [];
  for (const result of results) {
    if (!result.reference_id || !submitReferenceIds.has(result.reference_id)) {
      continue;
    }
    const actions = (result.data as { _actions?: unknown } | undefined)
      ?._actions;
    if (!Array.isArray(actions)) continue;
    for (const entry of actions) {
      if (isOutcome(entry)) outcomes.push(entry);
    }
  }
  return outcomes;
}

/** The human-readable text an instruction produced, when its `results`
 *  follow the `{message}` convention (or are a bare string). */
export function outcomeMessage(outcome: ActionOutcome): string | undefined {
  const results = outcome.results;
  if (typeof results === "string") return results.trim() || undefined;
  if (typeof results === "object" && results !== null) {
    const message = (results as { message?: unknown }).message;
    if (typeof message === "string" && message.trim()) return message;
  }
  return undefined;
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { collectActionOutcomes, outcomeMessage } from "./actionOutcomes";

const notify = {
  slug: "logging",
  instruction_type: "NOTIFY",
  results: { message: "fever with temp 39.2" },
};

describe("collectActionOutcomes", () => {
  it("reads _actions only from the questionnaire submit results", () => {
    const outcomes = collectActionOutcomes(
      [
        { reference_id: "qn-1", data: { id: "r1", _actions: [notify] } },
        {
          reference_id: "structured:symptom:q9",
          data: { _actions: [{ ...notify, slug: "not-mine" }] },
        },
        { reference_id: "qn-2", data: { id: "r2" } },
        { reference_id: "qn-3", data: { _actions: "garbage" } },
        { reference_id: "qn-3", data: { _actions: [{ nope: true }, notify] } },
        { data: { _actions: [notify] } },
      ],
      new Set(["qn-1", "qn-2", "qn-3"]),
    );
    assert.deepEqual(outcomes, [notify, notify]);
  });
});

describe("outcomeMessage", () => {
  it("uses the {message} convention or a bare string, else nothing", () => {
    assert.equal(outcomeMessage(notify), "fever with temp 39.2");
    assert.equal(outcomeMessage({ ...notify, results: "plain" }), "plain");
    assert.equal(outcomeMessage({ ...notify, results: "  " }), undefined);
    assert.equal(
      outcomeMessage({ ...notify, results: { message: "  " } }),
      undefined,
    );
    assert.equal(
      outcomeMessage({ ...notify, results: { other: 1 } }),
      undefined,
    );
    assert.equal(outcomeMessage({ ...notify, results: null }), undefined);
  });
});

