import { expect, test, type Page } from "@playwright/test";
import {
  adminApiHeaders,
  apiBaseUrl,
  createQuestionnaireAndOpenBuilder,
} from "tests/helper/questionnaireV2";
import { expectToast } from "tests/helper/ui";
import { getFacilityId } from "tests/support/facilityId";

test.use({ storageState: "tests/.auth/user.json" });

interface RegistryInstruction {
  slug: string;
  input_schema: { properties?: Record<string, { title?: string }> };
}

/** The first instruction the backend registry serves — the studio never
 *  hardcodes a slug, and neither does this spec. */
async function firstRegistryInstruction(): Promise<RegistryInstruction> {
  const res = await fetch(
    `${apiBaseUrl()}/api/v1/action_configuration/instructions/`,
    { headers: adminApiHeaders() },
  );
  if (!res.ok) throw new Error(`instructions endpoint: ${res.status}`);
  const data = (await res.json()) as { instructions: RegistryInstruction[] };
  if (data.instructions.length === 0) {
    throw new Error("The backend registers no action instructions");
  }
  return data.instructions[0];
}

/** Imports questions into the freshly-opened builder. */
async function importQuestions(page: Page, questions: object[]): Promise<void> {
  await page.getByRole("button", { name: "Import Questions" }).click();
  await page.locator('input[type="file"]').setInputFiles({
    name: "scaffold.json",
    mimeType: "application/json",
    buffer: Buffer.from(JSON.stringify({ questions })),
  });
  await page.getByRole("button", { name: "Import", exact: true }).click();
  await expectToast(page, "Questionnaire Imported Successfully");
}

async function fetchQuestionnaire(id: string) {
  const res = await fetch(`${apiBaseUrl()}/api/v1/questionnaire/${id}/`, {
    headers: adminApiHeaders(),
  });
  if (!res.ok) throw new Error(`questionnaire GET: ${res.status}`);
  return (await res.json()) as {
    actions: {
      condition: string;
      instructions: { slug: string; params: Record<string, unknown> }[];
    }[];
  };
}

test.describe("Questionnaire v2 actions authoring", () => {
  test("authors a conditional action with an answer in its message, saves, reloads and gates save on issues", async ({
    page,
  }) => {
    const instruction = await firstRegistryInstruction();
    const paramName = Object.keys(
      instruction.input_schema.properties ?? {},
    )[0];
    const paramLabel =
      instruction.input_schema.properties?.[paramName]?.title ?? paramName;
    const facilityId = getFacilityId();
    const stamp = Date.now();
    const feverTitle = `Fever ${stamp}`;
    const tempTitle = `Temperature ${stamp}`;

    const detailUrl = await createQuestionnaireAndOpenBuilder(page, {
      basePath: `/facility/${facilityId}/settings/questionnaires`,
      title: `QV2 Actions ${stamp}`,
    });
    const questionnaireId = detailUrl.split("/").pop() as string;
    await importQuestions(page, [
      { text: feverTitle, type: "boolean", link_id: "fever", required: true },
      { text: tempTitle, type: "decimal", link_id: "temp", required: true },
    ]);

    const actionsRow = page.getByRole("button", { name: /^Actions\b/ });
    const messageInput = page.getByRole("textbox", { name: paramLabel });

    await test.step("The outline's Actions row opens the empty panel", async () => {
      await actionsRow.click();
      await expect(page.getByText("No actions yet")).toBeVisible();
      await page.getByRole("button", { name: "Add action" }).click();
      await expect(page.getByText("Runs on every submission").first()).toBeVisible();
      // One registered instruction is preselected, so its input is ready.
      await expect(messageInput).toBeVisible();
    });

    await test.step("The message can splice an answer in at the caret", async () => {
      await messageInput.fill("Temp is ");
      await page
        .getByRole("button", { name: "Insert an answer or patient detail" })
        .click();
      await page.getByRole("menuitem", { name: `2. ${tempTitle}` }).click();
      await expect(messageInput).toHaveValue("Temp is {q_temp}");
      await expect(page.getByText("Preview:")).toBeVisible();
    });

    await test.step("A condition row defaults to the first answer", async () => {
      await page.getByRole("button", { name: "Add a condition" }).click();
      await expect(
        page.getByRole("combobox", { name: "Condition 1 Field" }),
      ).toContainText(feverTitle);
      await expect(
        page.getByRole("combobox", { name: "Condition 1 Value" }),
      ).toContainText("Yes");
    });

    await test.step("Save persists the compiled condition and template", async () => {
      await page.getByRole("button", { name: "Save Changes" }).click();
      await expectToast(page, "Questionnaire updated successfully");
      const saved = await fetchQuestionnaire(questionnaireId);
      expect(saved.actions).toHaveLength(1);
      expect(saved.actions[0].condition).toBe("q_fever == True");
      expect(saved.actions[0].instructions[0].slug).toBe(instruction.slug);
      expect(saved.actions[0].instructions[0].params[paramName]).toBe(
        '{{ f"Temp is {q_temp}" }}',
      );
    });

    await test.step("After a reload the card summarises the action in plain words", async () => {
      await page.reload();
      await page.getByRole("button", { name: /^Actions\b/ }).click();
      const card = page.getByRole("button", { name: "Action 1" });
      await expect(card).toBeVisible();
      await expect(page.getByText(`“${feverTitle}” equals “Yes”`)).toBeVisible();
      await card.click();
      await expect(messageInput).toHaveValue("Temp is {q_temp}");
    });

    await test.step("Removing the only step blocks Save through the issues popover", async () => {
      await page.getByRole("button", { name: "Remove step" }).click();
      await page.getByRole("button", { name: "1 to fix" }).click();
      await page
        .getByRole("button", { name: "An action needs at least one step" })
        .click();
      await page.getByRole("button", { name: "Add instruction" }).click();
      await expect(messageInput).toBeVisible();
      await messageInput.fill("Restored");
      await expect(page.getByText("Ready to save")).toBeVisible();
    });

    await test.step("Expression mode round-trips and guards an unparsable edit", async () => {
      await page.getByRole("button", { name: "Edit as expression" }).click();
      const expression = page.getByRole("textbox", { name: "Expression" });
      await expect(expression).toHaveValue("q_fever == True");
      await expression.fill("q_fever == True and (q_temp > 38)");
      await page.getByRole("button", { name: "Back to conditions" }).click();
      await expect(
        page.getByText("This expression can't be shown as conditions", {
          exact: false,
        }),
      ).toBeVisible();
      await page.getByRole("button", { name: "Keep expression" }).click();
      await expression.fill("q_fever == True and q_temp > 38");
      await page.getByRole("button", { name: "Back to conditions" }).click();
      await expect(
        page.getByRole("combobox", { name: "Condition 2 Field" }),
      ).toContainText(tempTitle);
      await expect(
        page.getByRole("spinbutton", { name: "Condition 2 Value" }),
      ).toHaveValue("38");
    });
  });
});

import { expect, test } from "@playwright/test";
import {
  fillStringField,
  submitAndExpectSuccess,
  submitForm,
} from "tests/helper/questionnaire";
import {
  adminApiHeaders,
  apiBaseUrl,
  questionBlock,
} from "tests/helper/questionnaireV2";
import { expectToast } from "tests/helper/ui";
import { getEncounterId } from "tests/support/encounterId";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

test.use({ storageState: "tests/.auth/user.json" });

/** The first instruction the backend registers (the `logging` smoke test
 *  today) — its first string input is what the message lands in. */
async function firstInstruction() {
  const res = await fetch(
    `${apiBaseUrl()}/api/v1/action_configuration/instructions/`,
    { headers: adminApiHeaders() },
  );
  const data = (await res.json()) as {
    instructions: {
      slug: string;
      input_schema: { properties?: Record<string, unknown> };
    }[];
  };
  const instruction = data.instructions[0];
  if (!instruction) throw new Error("No action instructions registered");
  return {
    slug: instruction.slug,
    paramName: Object.keys(instruction.input_schema.properties ?? {})[0],
  };
}

/** Authors an encounter questionnaire with actions straight through the
 *  API — this file is about what happens at fill time. */
async function createQuestionnaireWithActions(
  stamp: number,
  questions: object[],
  actions: object[],
): Promise<string> {
  const res = await fetch(`${apiBaseUrl()}/api/v1/questionnaire/`, {
    method: "POST",
    headers: adminApiHeaders(),
    body: JSON.stringify({
      title: `QV2 Fill Actions ${stamp}`,
      slug: `qv2-fill-actions-${stamp}`,
      version: "1.0",
      status: "active",
      subject_type: "encounter",
      auth_context: "instance",
      questions,
      actions,
    }),
  });
  if (!res.ok) {
    throw new Error(`questionnaire create: ${res.status} ${await res.text()}`);
  }
  return ((await res.json()) as { id: string }).id;
}

test.describe("Questionnaire v2 fill — actions", () => {
  test("an always-on action's message is shown after a successful submission", async ({
    page,
  }) => {
    const { slug, paramName } = await firstInstruction();
    const stamp = Date.now();
    const noteTitle = `Note ${stamp}`;
    const questionnaireId = await createQuestionnaireWithActions(
      stamp,
      [{ id: crypto.randomUUID(), link_id: "note", text: noteTitle, type: "string" }],
      [
        {
          condition: "True",
          instructions: [
            {
              slug,
              params: { [paramName]: `{{ f"Action ping {q_note}" }}` },
              context: "self",
            },
          ],
        },
      ],
    );

    await page.goto(
      `/facility/${getFacilityId()}/patient/${getPatientId()}/encounter/${getEncounterId()}/questionnaire/${questionnaireId}`,
    );
    await expect(questionBlock(page, noteTitle)).toBeVisible();
    await fillStringField(page, noteTitle, `hello-${stamp}`);
    await submitAndExpectSuccess(page);
    await expectToast(page, `Action ping hello-${stamp}`);
  });

  test("a referenced question left blank is flagged on the form instead of failing the submission", async ({
    page,
  }) => {
    const { slug, paramName } = await firstInstruction();
    const stamp = Date.now();
    const tempTitle = `Temperature ${stamp}`;
    const questionnaireId = await createQuestionnaireWithActions(
      stamp,
      [
        {
          id: crypto.randomUUID(),
          link_id: "temp",
          text: tempTitle,
          type: "decimal",
        },
        {
          id: crypto.randomUUID(),
          link_id: "note",
          text: `Note ${stamp}`,
          type: "string",
        },
      ],
      [
        {
          condition: "q_temp > 38",
          instructions: [
            { slug, params: { [paramName]: `High temp ${stamp}` }, context: "self" },
          ],
        },
      ],
    );

    await page.goto(
      `/facility/${getFacilityId()}/patient/${getPatientId()}/encounter/${getEncounterId()}/questionnaire/${questionnaireId}`,
    );
    await fillStringField(page, `Note ${stamp}`, "only the note");

    await test.step("Submit is blocked on the unanswered referenced question", async () => {
      await submitForm(page);
      await expect(
        questionBlock(page, tempTitle).getByText(
          "This answer is needed by the form's actions",
        ),
      ).toBeVisible();
    });

    await test.step("Answering it lets the submission through and the action fires", async () => {
      await questionBlock(page, tempTitle).getByRole("spinbutton").fill("39");
      await submitAndExpectSuccess(page);
      await expectToast(page, `High temp ${stamp}`);
    });
  });
});

